(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zh-tw"] = {"ui":{"skip":"跳到主要內容","back":"← 返回 AI-gile","lang.button":"語言：{name}","lang.dialog":"選擇語言","lang.search":"搜尋語言","lang.none":"沒有符合的語言","lang.notYet":"{name} 還沒有翻譯","theme.aria":"切換主題：淺色、深色或純黑","theme.toLight":"切換到淺色主題","theme.toDark":"切換到深色主題","theme.toBlack":"切換到純黑主題（真正的黑色，對 OLED 螢幕友善）","words.underline":"在頁面上為這些詞加底線","words.underlineHelp":"將游標移到虛線標示的詞上或點一下，就能看到它的意思。","words.col.todo":"暫時選定的卡片：團隊接下來會從這些開始。","words.col.doing":"有一個 AI 正在處理這張卡片。","words.col.review":"一個 AI 已完成工作，另一個 AI 檢查通過後才會交到你手上。","words.col.verify":"等你來：試一試，告訴我們好不好用。","words.col.team":"你的筆記或回答，等團隊來接手。","words.col.done":"已完成並通過驗收。","index.title":"AI-gile：你的 AI 開發團隊，都在一塊看板上","index.description":"AI-gile 是給 AI 程式開發團隊用的看板。你睡覺時他們在工作；你只會收到一小疊需要決定、測試和驗收的事。","hero.logoAlt":"AI-gile 看板圖示","hero.h1.html":"你的 AI 開發團隊，都在一塊&nbsp;看板上。","hero.alpha":"🐣 封閉式預 Alpha","hero.alphaTitle":"還早，也還沒做完：感謝你來試用！","hero.lede":"你睡覺時他們在開發。醒來只有一小疊事：幾個問題，幾樣要測試的東西，一兩顆紫色鑽石。點一點，驗收，接著去喝你的咖啡。","dl.windows":"Windows 應用程式","dl.browser":"在瀏覽器中執行","dl.messenger":"📱 手機版 Messenger","dl.soon":"即將推出","dl.notify":"🔔 開放時通知我","dl.notifySmall":"Alpha 或 Beta","hero.secondary":"敏捷開發，但團隊從不需要站立會議的咖啡。（不過他們還是照開站立會議。）","pitch.h2":"想用幾個字介紹 AI-gile，都行","pitch.lede":"選一個長度，從一個字到 144 個字。每個長度都是專門為這個篇幅寫的一段介紹。拖曳滑桿，或用方向鍵。","pitch.rangeLabel":"字數","pitch.dice":"🎲 換一個版本","pitch.words.one":"{n} 個詞","pitch.words.other":"{n} 個詞","pitch.letters.one":"{n} 個字母","pitch.letters.other":"{n} 個字母","pitch.chars.one":"{n} 個字","pitch.chars.other":"{n} 個字","count.line.html.one":"看板上現在有 {n} 張卡片","count.line.html.other":"看板上現在有 {n} 張卡片","people.humans.html.one":"👥 {n} 位人類","people.humans.html.other":"👥 {n} 位人類","people.agents.html.one":"🤖 {n} 個 AI 代理","people.agents.html.other":"🤖 {n} 個 AI 代理","people.working.html.one":"⚡ 此刻 {n} 個正在工作","people.working.html.other":"⚡ 此刻 {n} 個正在工作","pre.title":"AI-gile：有東西正在打造","pre.description":"這裡正在悄悄打造一些東西：一塊讓 AI 團隊照你的要求來做、還邊做邊教你的看板。目前是和朋友們一起的封閉式預 Alpha。","pre.h1":"這裡正在悄悄打造一些東西。 🤫","pre.line":"一塊讓 AI 團隊照你的要求來做、還邊做邊教你的看板。目前是和朋友們一起的封閉式預 Alpha。","pre.btn":"🔔 開放時通知我","pre.peek":"玻璃後面：真實的看板，即時。每張卡片都是一條彩色橫條。","pre.peekFake":"玻璃後面：一塊正在運作的看板就是這個樣子。","pre.night":"🌙 守夜人正在當家 · 😴 人類正在休息","features.aria":"它能做什麼","f.pile.h":"給你的一小疊","f.pile.html":"<b>待你處理</b>匯集了所有專案裡等你的事：問題、要測試的東西、只有人能做的任務。你的佇列會告訴你下一件是什麼、要花多久。","f.sleep.h":"你睡覺時也在工作的團隊","f.sleep.p":"每個專案都有一位負責人和一隊 AI 代理程式。在卡片上留言，團隊就會醒來工作，再帶著疲憊的人也能照著做的步驟交還給你。","f.tester.h":"先由 AI 測試員檢查","f.tester.p":"東西送到你面前之前，測試員會在應用程式的副本裡照著步驟操作，並附上截圖說明看到了什麼。通過的快速翻一翻，一鍵驗收。","f.proof.h":"有證據，不畫餅","f.proof.p":"每次交付都會列出改了什麼：檔案、差異、截圖。不用逐一打開應用程式去確認做完了沒有。","f.chat.h":"和你的負責人聊天","f.chat.p":"類似 Discord 的側欄：每個專案一個圖示，需要你的事用紫色鑽石標出。把想法傳給負責人，他們會整理成卡片和計畫，並附上「✅ 開始」按鈕。","f.tidy.h":"自己保持整潔","f.tidy.p":"相關卡片合併成一張，含糊的標題會被改清楚，用量檢查讓程式碼保持精簡。要切換的東西更少，要操心的也更少。","f.private.h":"屬於你，就在你的電腦上","f.private.li1":"看板執行在你自己的電腦上，只聽你的。","f.private.li2":"人與人之間的私訊採用端對端加密。","f.private.li3":"沒有帳號，沒有追蹤器，沒有 Cookie。","f.lang.h":"說你的語言","f.lang.p":"支援 120 多種語言，從荷蘭語、威爾斯語、日語，到海盜腔、尤達腔和克林貢語，專業術語還能一鍵切回英文。","f.service.h":"從一個點子到一項真正的服務","f.service.p":"用 AI 做出了已經有人在用的東西？把它標記為服務，看板就會幫你把它營運好：可用性檢查、公開的狀態頁、附上事後檢討的事故、需要 Go 才能上線的變更、每天檢查的備份。說明會在你操作時一步步教你。","msgr.h2":"AI-gile Messenger：把團隊裝進口袋","msgr.p1":"不用打開看板，也能和你的 AI 團隊聊天。跟專案負責人和朋友們聊聊，查看卡片的測試步驟並直接回覆，全在手機上搞定。","msgr.p2":"掃描看板上的 QR 碼即可配對。第一次用？親切的示範聊天會帶你四處看看。","msgr.when":"先推出 Android 版，接著是適用手機和 iPhone 的網頁版。","msgr.who":"你的專案負責人","msgr.b1":"深色模式修好了。要看測試步驟嗎？","msgr.b2":"好啊，麻煩了！","msgr.b3":"1. 打開設定。2. 選擇深色。看起來對嗎？","tl.aria":"從第一次對話到路線圖的時間軸","tl.h2":"從第一次聊天到接下來的計畫","tl.lede":"真實的日期和時間，依你自己的時區顯示。今天之後就是計畫，不承諾具體日期。","tl.today":"今天","tl.planned":"計畫中","tl.doing":"進行中","tl.cards.one":"{n} 張卡片","tl.cards.other":"{n} 張卡片","join.h2":"一起來玩","join.lede":"AI-gile 由一個大鬍子怪咖（有 AuDHD，跟心理健康打過幾場仗）和一大群有耐心的代理程式打造。目前不公開，只在朋友間封閉內測。開放時想試試嗎？","join.btn":"登記興趣","join.small":"只會寄信給你，別無其他","footer.tag":"AI-gile。沒有追蹤器，沒有 Cookie，沒有站立會議咖啡。","footer.licence":"商業授權","footer.status":"狀態","footer.privacy":"我們保存什麼","footer.thanks":"通話感謝 ChilledChat","form.sending":"傳送中…","form.failed":"沒成功：請稍後再試。","form.offline":"連不上 AI-gile：請稍後再試。","form.keep":"我們只用它來回覆你，之後就會刪除。沒有追蹤器，沒有 Cookie。","form.keepLink":"我們保存什麼","interest.title":"AI-gile：Alpha 開放時通知我","interest.description":"留下電子郵件，AI-gile 的封閉式 Alpha 或 Beta 開放時我們會告訴你。","interest.h1":"🔔 開放時通知我","interest.lede":"AI-gile 正處於封閉式預 Alpha 階段。留下電子郵件，等有你的位置時，我們只寫一封信。","interest.email":"你的電子郵件","interest.which":"哪種測試？","interest.alpha":"封閉式 Alpha：早期、粗糙、變動多","interest.beta":"Beta：更穩定，更晚","interest.both":"都行，哪個先開就哪個","interest.submit":"把我加入名單","interest.thanks":"謝謝！你已在名單上。","licence.title":"AI-gile：商業授權","licence.description":"要在公司裡使用 AI-gile？可以免費申請商業授權。","licence.h1":"📜 商業授權","licence.lede":"想在工作中使用 AI-gile？告訴我們你是誰、做什麼。只要做的事有益處，授權就是免費的。","licence.company":"公司","licence.website":"網站","licence.what":"你做什麼","licence.how":"它如何幫助世界","licence.email":"電子郵件","licence.submit":"申請","licence.thanks":"謝謝！我們會透過電子郵件回覆。","status.title":"AI-gile 狀態","status.h1":"AI-gile 狀態","status.quiet":"一切平靜","status.intro":"AI-gile 現在正常嗎？這個頁面每 5 分鐘檢查一次網站、看板分享、通話和下載。","status.up":"正常運作（{ms} ms 內回應）","status.slow":"上次檢查沒有回應，正在重試","status.down":"停止運作：最近兩次檢查都沒有回應","status.svc.web":"網站","status.svc.web.offers":"本網站：介紹 AI-gile，以及「開放時通知我」表單","status.svc.boards":"看板分享","status.svc.boards.offers":"公開看板、朋友之間的訊息和邀請","status.svc.calls":"通話","status.svc.calls.offers":"AI-gile 裡的語音、視訊和螢幕分享","status.svc.download":"下載","status.svc.download.offers":"Windows 安裝程式和邀請連結","status.checking":"檢查中…","status.offline":"暫時連不上狀態服務（正在重試）","status.updated":"更新於{ago}","status.justNow":"剛剛","status.min":"{n} 分鐘前","status.hours":"{n} 小時前","status.days":"{n} 天前","privacy.title":"AI-gile：我們保存什麼","privacy.h1":"我們保存什麼","privacy.lede":"簡單說：只保存你傳給我們的內容，而且不會太久。","privacy.only":"只有你傳給我們的內容：你在表單裡輸入的東西，例如你的電子郵件。除此之外，沒有任何關於你的資料。","privacy.sealed":"內容會先密封，我們的伺服器無法讀取：在離開你的瀏覽器之前就已密封（若是較舊的瀏覽器，則在送達的那一刻密封）。只有我們自己的看板能打開它。","privacy.server":"一送達我們的看板，就會從伺服器上刪除。30 天後仍留在那裡的任何內容，也一律刪除。","privacy.board":"我們只在回覆你之前把它留在看板上，回覆後也會從那裡刪除。","privacy.none":"沒有追蹤器，沒有 Cookie，沒有分析工具。","privacy.local":"你的語言以及淺色或深色的選擇只會留在你自己的瀏覽器裡，絕不會傳給我們。","privacy.ask":"想早點刪除？回覆我們的電子郵件告訴我們就行。","live.h2":"即時看它是怎麼建起來的","live.caption":"每張卡片都是隱藏的：你看到的是工作的樣子，而不是文字。","live.watching.one":"即時：{n} 人正在看","live.watching.other":"即時：{n} 人正在看","live.last.now":"最近一張卡片剛剛移動","live.last.min.one":"最近一張卡片在 {n} 分鐘前移動","live.last.min.other":"最近一張卡片在 {n} 分鐘前移動","live.last.hour.one":"最近一張卡片在 {n} 小時前移動","live.last.hour.other":"最近一張卡片在 {n} 小時前移動","live.last.day.one":"最近一張卡片在 {n} 天前移動","live.last.day.other":"最近一張卡片在 {n} 天前移動","live.offline":"即時看板正在稍作休息，請稍後再來看看。","live.cols":"Backlog|待辦|進行中|團隊檢查中|待你測試|交給團隊|已完成","footer.models":"AI-gile 會替你調用 AI 模型做事。它們說的話、做的事由它們自己負責，所以在相信之前請先查證。","privacy.ai.h":"AI 部分","privacy.ai.models":"AI-gile 是看板。真正做事的是其他公司的 AI 模型，例如 Claude、Codex 和 Gemini，用的是你自己的帳號。","privacy.ai.check":"它們寫的內容和做的事都出自它們，可能是錯的。在依賴或發布之前，請先檢查。","privacy.ai.files":"它們會修改你所連接資料夾裡的檔案，並執行指令。請做好備份。","privacy.ai.send":"你交給模型的內容會傳送給營運它的公司，並適用對方的條款。每家公司各自的條款和費用都會生效。","privacy.ai.asis":"AI-gile 是早期測試版，依現況提供。"},"lines":{"unit":"chars","sizes":[{"n":1,"texts":["看板。","機器人。","放手。"]},{"n":2,"texts":["機器人看板。","代理，有序。","想法，成真。"]},{"n":3,"texts":["給機器人的看板。","想法變成功能。","免費代理看板。"]},{"n":5,"texts":["由代理程式運轉的看板。","你寫卡片，代理來做。","免費、本機、有測試，還有點傻氣。"]},{"n":8,"texts":["一塊免費的看板，AI 代理程式在上面工作。","寫下想法，代理去做，最後由你驗收。","給一個人類和一群耐心機器人用的敏捷。"]},{"n":13,"texts":["一塊在你電腦上的看板，AI 代理程式會自己來領卡片工作。","寫下一個想法，一隊代理程式動手做，再由測試員檢查一遍。","免費，沒有帳號，沒有追蹤器：一塊看板，幾個機器人，你說了算。"]},{"n":21,"texts":["AI-gile 是一塊用來和 AI 程式開發代理合作的看板。卡片由它們去領，測試和驗收則交給你來做。","每個專案都有一位負責人和一隊 AI 代理程式。你在任何一張卡片上留言，團隊就會開始動手工作。","這是一塊免費的個人待辦看板，就執行在你自己的電腦上。做事的是機器人，點頭說好的人是你。"]},{"n":34,"texts":["你把想法放到看板上，一隊 AI 代理程式把它們做成能用的功能，自己測試一遍，再附上試用步驟交還給你。你沒點頭之前，沒有任何東西算完成。","AI-gile 是一塊自製的看板，Rich 在如今被它管理的代理程式們的大力幫助下造出了它。它免費，執行在你的電腦上，只分享給朋友，從不販售。","想像一塊普通的看板，欄位從待辦排到已完成，只不過卡片是由 AI 代理程式來領的。它們會回報進度，卡住時會提問，而且永遠等著你點頭同意。"]},{"n":55,"texts":["AI-gile 是一塊團隊由 AI 代理程式組成的看板。每個專案都有一位負責規劃的負責人，和幾位動手開發的助手。功能做好後，AI 測試員會先試用並截圖，然後才放進你的那一小疊。你可以驗收，也可以留言，他們就會返工重做。","它起初只是一個人用來同時盯著許多 AI 程式開發工作階段的辦法，後來慢慢長成了一塊像樣的看板。它執行在你的電腦上，不需要帳號，也沒有追蹤器。朋友和好奇的人都可以免費使用。它還沒做完，所以難免有些毛躁，偶爾也會有小意外。","說句實話：想法還得你來想，結果還得你來看。AI-gile 管的是中間所有的事：讓卡片井然有序，你一留言就叫醒該醒的代理程式，清楚展示究竟改了什麼，再把這一切收進給你的一小疊裡。另外它在你的電腦上執行，不要帳號，也沒有任何追蹤器，完全免費，你想怎麼用都行，隨時可以停。"]},{"n":89,"texts":["AI-gile 是一塊免費的看板，執行在你自己的電腦上。每個專案裡做事的不是人，而是一隊 AI 代理程式：負責人把你的想法整理成卡片和計畫，助手則依優先順序領取卡片。做好之後，AI 測試員會照著測試步驟操作，並給你看它看到了什麼。接著它會放進標著待你處理的那一小疊裡等你。你可以驗收，也可以留言讓團隊再來一輪。沒有你點頭，任何東西都到不了已完成。","有幾個你也許想不到的功能。夜班守望會在你睡覺時替待辦欄補貨，專挑不需要你回答的卡片。用量計數器會顯示代理程式今天和本週用了多少，省用模式則讓它們停止消耗。你可以傳訊息給朋友，私訊採用端對端加密。看板支援大約 120 種語言，包括荷蘭語、法蘭德斯語、海盜腔和克林貢語。這一切一毛錢都不收，也沒有人想把它賣給你。它執行在你自己的電腦上，不需要帳號，也沒有追蹤器和 Cookie，資料始終留在你手裡。","AI-gile 是一個小小的個人專案，不是公司。Rich 想同時照看好幾個 AI 程式開發專案，又不想一個個打開應用程式去查看，於是他和代理程式們一起造了這塊看板，又用這塊看板造出了它自己的其餘部分。它處於封閉式預 Alpha 階段，意思是對少數幾位朋友來說，大致上能用。這裡沒有價格頁，沒有電子報，也沒有成長計畫。如果你覺得有用，等它再開放一些，可以申請試用。"]},{"n":144,"texts":["AI-gile 是給一個人類和許多 AI 代理程式用的看板。它執行在你自己的電腦上，完全免費。你新增專案，每個專案都會有一位負責人和一支小團隊。你可以和負責人聊天，有點像 Discord，把想法講給他聽；他會把想法整理成卡片和計畫，然後等你按下開始。團隊依優先順序逐張處理卡片，用的是一套專門為語言模型設計的簡單命令列。任何東西回到你手裡之前，AI 測試員都會在應用程式的副本裡照著步驟操作，並附上截圖。做完的工作連同更動的檔案和差異，一起落進你的那一小疊。你可以驗收，也可以留下一則留言，團隊就會醒來再試一次。只有你能把卡片移到已完成。","大致說說和 AI-gile 度過的一天。傍晚你留下幾則留言：這個按鈕位置不對，那份清單該排個序，能不能加個深色模式。然後你去睡覺。代理程式們讀完留言，動手修改，測試，再交還給你。如果待辦欄空了，夜班守望就從待辦清單裡補貨，挑那些不需要你回答的卡片。早上你面前只有一小疊：幾個問題，幾樣要試的東西，每樣都有睡眼惺忪的人也能照做的步驟，還有一張證明它能用的截圖。你一路點過去，好的驗收，其餘的退回，寫一句話告訴它們哪裡不對就行。用量計數器會告訴你這一切花了多少，節儉的幾週還有省用模式可以開。每個專案各有各的負責人，各有各的團隊，互不打擾。然後你去吃早餐，這一步代理程式暫時還幫不上忙。","先說說 AI-gile 不是什麼。它不是新創公司，不對外販售，也沒有人在蒐集你的資料。它是一塊免費的看板，執行在你的電腦上，沒有帳號，沒有追蹤器，也沒有 Cookie。它是什麼呢：一個整潔的地方，能一眼看到所有 AI 程式開發專案，一隊代理程式負責做卡片，決定則由你來下。它會把相關的卡片合併，把含糊的標題改清楚，還留意程式碼是不是保持精簡。它支援大約 120 種語言，從荷蘭語、法蘭德斯語到海盜腔和克林貢語。朋友之間可以私下傳訊息，而且是加密的。它由 Rich 和一大群有耐心的代理程式打造，多半是靠它自己來完成的。它仍處於封閉式預 Alpha 階段，有些地方還很粗糙。如果聽起來有趣，客氣地問一問，也許你能提前進來。"]}],"quips":{"1":"就一個詞。夠大膽。也許太大膽了。","3":"三個詞。已經比大多數產品頁更誠實了。","8":"八個詞。還是比一次站立會議短。","21":"順帶一提，這些長度是故事點數。那當然。","55":"五十五個詞。你讀這段的工夫，有兩張卡片做完了。","144":"這是最長的一版。沒有 233 了。代理程式已經去睡了。"}},"timeline":{"first-idea.name":"最初的想法","first-idea.line":"第一次對話，那時還沒有任何程式碼。","first-board.name":"第一塊看板","first-board.line":"一塊記錄自己如何被造出來的看板：卡片、欄、拖放、專案。","team-roles.name":"團隊與角色","team-roles.line":"代理程式檔案、團隊範本、空間，以及誰負責什麼。","install.name":"安裝與發布","install.line":"朋友也能安裝的壓縮檔、自動更新、管道和還原。","usage-saver.name":"用量節省","usage-saver.line":"衡量每次執行的花費，保持程式碼精簡，省下你的額度。","friends.name":"好友與分享","friends.line":"私訊、加擾中繼、邀請、角色和共享專案。","languages.name":"語言","languages.line":"所有介面文字都放進語言檔，先有荷蘭語和法蘭德斯語。","ai-tester.name":"AI 測試員","ai-tester.line":"每次交付先由測試員檢查，並展示它看到的內容。","website.name":"網站","website.line":"aigile.lol、預告頁和這條時間軸。","streaming.name":"聊天與直播","streaming.line":"Discord、Twitch、OBS、實況主模式、GIF 和表情符號。","no-ai.name":"無 AI 版","no-ai.line":"給不用 AI 寫程式的人用的看板，以及公開看板。","night-watch.name":"夜班守望","night-watch.line":"守夜人和 Scrum Master 在你睡覺時盯著團隊工作。","p-more.name":"其他一切","p-more.line":"還在排隊等輪到的小想法。","p-android.name":"手機與 Android","p-android.line":"先用手機存取你的看板，再做原生 Android 應用程式。","p-release.name":"Alpha 及以後","p-release.line":"封閉式 Alpha、正式上線的網站，然後是 Beta。","p-languages.name":"更多語言","p-languages.line":"130 種語言，還有給學習者的語言沉浸模式。","p-engines.name":"更多 AI 引擎","p-engines.line":"每個代理都能選用 Claude、Codex、Gemini、Copilot 或 Cursor。","p-pro.name":"專業實務","p-pro.line":"風險標籤、合併關卡、事故卡片和護欄。","p-self.name":"照顧你自己","p-self.line":"疲憊模式、自我關懷提醒和 4:20。","p-servers.name":"伺服器與規模","p-servers.line":"全域伺服器設定、角色，以及為成長做的規劃。","p-livestream.name":"直播附加功能","p-livestream.line":"Twitch 聊天、自訂表情符號和公開的直播檢視。"},"words":{"button":"📖 專業術語","h":"📖 名詞解釋","intro":"白話易懂的免費教學：從最初的想法到人們依賴的服務，你會遇到的每個詞都在這裡，沿途還涵蓋敏捷、開發、確保安全，以及與 AI 合作。","search":"搜尋詞彙…","none":"沒有符合的詞。","close":"關閉","count":{"one":"{count} 個詞","other":"{count} 個詞"},"groups":[{"id":"idea","name":"💡 發想與探索"},{"id":"plan","name":"🗺️ 規劃工作"},{"id":"agile","name":"🔁 敏捷工作方式"},{"id":"build","name":"🛠️ 做出來"},{"id":"test","name":"🧪 測試與品質"},{"id":"change","name":"🔀 安全地變更"},{"id":"run","name":"🛎️ 營運一項服務"},{"id":"sec","name":"🔒 安全與隱私"},{"id":"ai","name":"🤖 與 AI 合作"},{"id":"money","name":"💰 費用與授權"}],"list":[{"id":"discovery","g":"idea","word":"探索期（Discovery）","text":"最早的階段：在動手做任何東西之前，先弄清楚哪個問題值得解決、是為誰解決。","also":["探索階段","發現階段","discovery phase"]},{"id":"problemstmt","g":"idea","word":"問題陳述","text":"用一兩句話說清楚誰有什麼問題、為什麼重要，讓大家朝著同一個目標努力。","also":["問題陳述","problem statements"]},{"id":"user","g":"idea","word":"使用者","text":"使用你所做東西的人。做這些工作，就是為了滿足他們的需求。","also":["使用者","用戶","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"利害關係人","text":"關心工作結果、或會受其影響的人，例如出錢的人、使用的人和提供支援的人。","also":["利害關係人","利益相關者","stakeholders"]},{"id":"persona","g":"idea","word":"使用者輪廓（Persona）","text":"一個虛構但真實可信的人物，代表某一類使用者，讓團隊可以問：「小山會覺得這個好用嗎？」","also":["使用者輪廓","人物誌","personas"]},{"id":"userresearch","g":"idea","word":"使用者研究","text":"和真實的人交談、觀察他們，了解他們的需求，而不是靠猜。","also":["使用者研究","使用者訪談","user interviews"]},{"id":"journey","g":"idea","word":"使用者旅程","text":"一個人完成某件事所經歷的步驟，從第一次聽說到最後做完，也包括在你的產品之外的部分。把它畫出來，就能看出他們在哪裡卡住。","also":["使用者旅程","顧客旅程","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"痛點","text":"現在讓人煩惱或拖慢人的事情。好的產品會把痛點消除。","also":["痛點","pain points"]},{"id":"assumption","g":"idea","word":"假設","text":"你相信、但還沒有驗證過的事。把假設寫下來，就知道該先測試什麼。","also":["假設","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"假說","text":"打算去驗證的一個最佳猜想，並寫明預期會發生什麼，例如「第一個月免費的話，大家就會註冊」。","also":["假說","hypotheses"]},{"id":"experiment","g":"idea","word":"實驗","text":"一次有計畫的小測試，在下大賭注之前先弄清楚一個想法行不行得通。","also":["實驗","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"概念驗證（PoC）","text":"快速做個粗糙的嘗試，看看一個想法到底行不行。有了答案之後，通常就丟掉。","also":["PoC","概念驗證","proof of concept"]},{"id":"prototype","g":"idea","word":"原型","text":"產品的早期模型，常常是可以點擊的圖片，在正式製作之前先讓人試用這個想法。","also":["原型","prototypes"]},{"id":"wireframe","g":"idea","word":"線框圖","text":"一張簡單的畫面草圖，只標出各樣東西放在哪裡，沒有顏色，也沒有真實內容。","also":["線框圖","wireframes"]},{"id":"mockup","g":"idea","word":"視覺稿（Mockup）","text":"一張詳細的圖，呈現畫面最終的樣子，有真實的顏色和文字，但還什麼都點不動。","also":["視覺稿","擬真圖","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"商業論證","text":"做一個專案的理由：要花多少錢、能帶來或省下多少、有哪些風險。","also":["商業論證","商業案例","business cases"]},{"id":"feasibility","g":"idea","word":"可行性","text":"以你現有的時間、資金和技能，這件事是否真的做得出來並維護下去。","also":["可行"]},{"id":"outcome","g":"idea","word":"成果（Outcome）","text":"你希望為人們帶來的改變，例如減少錯過的預約。它比做了多少東西更重要。","also":["成果","成效","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"產出（Output）","text":"團隊做出來的東西，例如一個新畫面或一份報告。做出來並不等於對誰有幫助。","also":["產出","交付物","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"成功指標","text":"一個數字，告訴你這項工作有沒有達到目的，例如有更多人完成了下單。","also":["成功指標","success metrics"]},{"id":"kpi","g":"idea","word":"關鍵績效指標（KPI）","text":"用來看事情進展順不順利的重要數字，例如每週註冊人數。","also":["KPI","KPIs","關鍵績效指標","key performance indicator"]},{"id":"okr","g":"idea","word":"目標與關鍵成果（OKR）","text":"一種設定目標的方法：目標說明你想要什麼，幾個關鍵成果則是證明你做到了的數字。","also":["OKR","OKRs","目標與關鍵成果"]},{"id":"product","g":"plan","word":"產品","text":"為使用者而開發和維護的東西，例如應用程式、網站或工具。","also":["產品","products"],"noTip":1},{"id":"vision","g":"plan","word":"產品願景","text":"一段簡短的話，說明產品幫助誰，以及長遠來看要走向哪裡。","also":["願景","願景宣言","vision statement"]},{"id":"po","g":"plan","word":"產品負責人（PO）","text":"決定做什麼、依什麼順序做的人，讓團隊始終做最重要的事。在 AI-gile 裡，這個人就是你。","also":["PO","產品負責人","product owners"]},{"id":"pm","g":"plan","word":"產品經理（PM）","text":"負責產品方向的人：它解決哪些問題、為誰解決、為什麼。PM 也可能指專案經理，所以要看清楚是哪一種。","also":["產品經理","product managers"]},{"id":"projmgr","g":"plan","word":"專案經理","text":"讓專案準時、不超出預算的人，負責追蹤誰在什麼時候做什麼。","also":["專案經理","project managers"]},{"id":"roadmap","g":"plan","word":"路線圖","text":"對未來幾個月要做什麼的大致計畫，依先後排列。它顯示方向而不是確切日期，會隨著你的了解而調整。","also":["路線圖","roadmaps"]},{"id":"milestone","g":"plan","word":"里程碑","text":"專案中值得標記的一個節點，例如「第一版上線」或「達到 100 位使用者」。","also":["里程碑","milestones"]},{"id":"mvp","g":"plan","word":"最小可行產品（MVP）","text":"仍然對真實使用者有用的最小版本，這樣你能及早向他們學習。","also":["MVP","MVPs","最小可行產品","minimum viable product"]},{"id":"requirement","g":"plan","word":"需求","text":"做好的產品必須能做到或必須具備的東西。","also":["需求","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"範圍","text":"工作包含什麼，以及同樣重要的：不包含什麼。","also":["範圍內","範圍外","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"範圍蔓延","text":"工作內容一點一點越加越多，卻沒人同意多花時間或費用，結果永遠做不完。","also":["需求蔓延","功能蔓延","feature creep"]},{"id":"feature","g":"plan","word":"功能","text":"產品能為人做的一件事，例如「重設密碼」。","also":["功能","features"],"noTip":1},{"id":"epic","g":"plan","word":"史詩（Epic）","text":"一大塊工作，一次做不完，所以要拆成較小的卡片。","also":["史詩","epics"]},{"id":"story","g":"plan","word":"使用者故事","text":"從使用者角度寫的一小塊工作：「身為購物者，我想儲存購物籃，以便稍後再結帳。」它是討論該做什麼的起點。","also":["使用者故事","user stories"]},{"id":"ac","g":"plan","word":"驗收標準（AC）","text":"一張卡片要算完成所必須通過的檢查，在開工前就談好，例如「登出再登入後，購物籃裡的東西還在」。","also":["驗收標準","acceptance criteria"]},{"id":"task","g":"plan","word":"任務","text":"一件要做的具體事情，通常是一個較大故事中的一小步。","also":["任務","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"工單","text":"卡片的另一種叫法：一項工作或一個請求，從開始到結束全程追蹤。","also":["工單","tickets"]},{"id":"priority","g":"plan","word":"優先順序","text":"相較於其他事情，某件事有多重要或多緊急，讓最重要的工作先做。","also":["優先順序","優先級","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"排優先順序","text":"依重要程度替工作排序。常見的方法是 MoSCoW：必須有、應該有、可以有、這次不做。","also":["排優先順序","優先排序","MoSCoW"]},{"id":"estimate","g":"plan","word":"估算","text":"對一項工作有多大、要多久的最佳猜測。它只是猜測，不是承諾。","also":["估算","估計","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"故事點數","text":"透過卡片之間互相比較（「大約是那張的兩倍」）而不是用小時來估計工作量的方法。故事點數不是用來比較不同團隊的。","also":["故事點數","故事點","story point"]},{"id":"tshirt","g":"plan","word":"T 恤尺寸估算","text":"把工作量估成 S、M、L 或 XL。又快又夠用，適合早期規劃。","also":["T恤尺寸","t-shirt sizes"]},{"id":"poker","g":"plan","word":"規劃撲克","text":"一種估算遊戲：大家同時亮出代表大小的牌，然後出最高和最低的人說明理由。","also":["估算撲克","Scrum poker"]},{"id":"dependency","g":"plan","word":"相依性","text":"一項工作必須等另一項開始或完成，自己才能開始或完成。","also":["相依性","依賴關係","dependencies"]},{"id":"blocker","g":"plan","word":"阻礙","text":"現在讓工作無法繼續的任何事，例如還沒得到回覆或工具壞了。","also":["阻礙","卡關","blockers"]},{"id":"deadline","g":"plan","word":"截止日期","text":"某件事必須完成的日期。","also":["截止日期","最後期限","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"交付物","text":"工作產出並交出去的具體東西，例如一個能用的頁面或一份報告。","also":["交付物","可交付成果","deliverables"]},{"id":"forecast","g":"plan","word":"預測","text":"根據目前所知，對可能發生的事（例如工作什麼時候完成）做出的預判。","also":["預測","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"指標","text":"任何你持續測量和追蹤的東西，例如頁面瀏覽量或修復一個問題要多久。","also":["指標","度量","metrics"]},{"id":"feedback","g":"plan","word":"回饋","text":"別人對你的工作說的話，無論好壞。及早、經常地得到回饋，是敏捷的核心。","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"尚未排進計畫的想法和工作的等候清單，最重要的放在最上面。在移到「待辦」之前，那裡的東西都不會有人去做。"},{"id":"sprint","g":"agile","word":"Sprint","text":"一段短而固定的工作時間（通常一到兩週，最長不超過一個月），有一個目標和一組說好要完成的卡片。","also":["sprints","衝刺"]},{"id":"standup","g":"agile","word":"站立會議","text":"每天一次的快速碰頭：每位成員做了什麼、接下來做什麼、有什麼阻礙。在 Scrum 裡叫每日 Scrum。","also":["站立會議","每日站立會議","standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"看板","text":"一種工作方式：卡片在看板的各欄之間移動（例如待辦、進行中、已完成），團隊限制同時進行的數量，讓工作持續流動。"},{"id":"wip","g":"agile","word":"WIP 限制","text":"WIP 是在製品（work in progress）的縮寫。WIP 限制是一欄最多可以同時放幾張卡片，讓團隊先把事情做完，再開始新的。","also":["WIP"]},{"id":"dod","g":"agile","word":"完成的定義","text":"團隊對「完成」是什麼意思的簡短清單，例如已測試、已說明，然後才把卡片交給你。它的雙胞胎「就緒的定義」，說的是卡片什麼時候清楚到可以開工。","also":["就緒的定義","DoD","DoR","Definition of Ready"]},{"id":"retro","g":"agile","word":"回顧","text":"定期回頭看團隊是怎麼工作的，說好一兩件下次能做得更好的事。是 retrospective 的簡稱。在 AI-gile 裡，回顧會議會提議改動團隊的工作方式，由你回答 Go 或「還不行」。","also":["回顧會議","Retro","retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"蜂群","text":"全員上陣：許多人放下手邊別的工作，一起處理一件緊急的事，直到解決為止。在 AI-gile 裡，每個團隊都來幫一個專案，其他專案暫時等著。","also":["全員投入","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"在 Scrum 裡，幫助團隊順利工作的人：清除他們的阻礙、讓會議保持在正軌上、指導好習慣，而不是對人發號施令。在 AI-gile 裡，首席 Scrum Master 會在所有專案中找出卡住的卡片、催一催各團隊，並提醒你有什麼在等你。","also":["首席 Scrum Master","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"敏捷（Agile）","text":"一種分小步的工作方式：先做一點，經常展示真實成果，從大家的意見中學習，邊做邊調整計畫，而不是一開始就把一切都規劃好。","also":["敏捷","敏捷開發","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"敏捷宣言","text":"軟體開發者在 2001 年寫下的一段簡短宣言。它把人、能運作的成果、與客戶密切合作和因應變化，放在繁重的計畫和文書工作之前。","also":["敏捷宣言","敏捷軟體開發宣言","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"瀑布模型","text":"較老的工作方式：先把一切計畫好，再全部做出來，然後全部測試，一個階段接一個階段。到了後期再改動，既困難又昂貴。","also":["瀑布模型","瀑布式","waterfall model"]},{"id":"iteration","g":"agile","word":"迭代","text":"一輪「做出東西、檢查、改進」的過程。敏捷工作就是由一連串迭代組成的，而衝刺就是其中一種。","also":["迭代","疊代","iterations"]},{"id":"increment","g":"agile","word":"增量","text":"在一次衝刺或一輪工作中加到產品裡的一塊新的、能用的部分，並且能與原有的部分配合起來。","also":["增量","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"一種流行的敏捷工作方式：一個小團隊在短短的衝刺裡朝著一個目標努力，有固定的角色和幾個定期的會議，用來計畫、檢查和改進。"},{"id":"scrumteam","g":"agile","word":"Scrum 團隊","text":"Scrum 裡做事的那個小組：一位產品負責人、一位 Scrum Master 和開發人員。","also":["Scrum 團隊","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum 事件","text":"Scrum 裡的定期會議：衝刺計畫會議、每日 Scrum、衝刺審查會議和回顧會議。很多人把它們叫作「儀式」（ceremonies）。","also":["Scrum 事件","Scrum 會議","儀式","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"衝刺計畫會議","text":"衝刺開始時的會議，團隊在會上一起說好這次衝刺為什麼重要、要接哪些卡片，以及怎麼著手。","also":["衝刺計畫會議","計畫會議","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"衝刺目標","text":"用一句話說明這次衝刺是為了什麼。小任務可以在途中調整，只要目標達成就行。","also":["衝刺目標","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"衝刺待辦清單","text":"為目前衝刺挑選出來的卡片，以及團隊完成它們的計畫。","also":["衝刺待辦清單","衝刺 Backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"產品待辦清單","text":"為產品可能要做的所有事情排好序的完整清單，最重要的在最上面。它會隨著你的了解不斷變化。","also":["產品待辦清單","產品 Backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"產品目標","text":"產品努力要達成的更大成果，幫助團隊決定下一步做什麼。","also":["產品目標","product goals"]},{"id":"refinement","g":"agile","word":"Backlog 梳理（Refinement）","text":"定期檢視 Backlog，整理、拆分、排序，並替卡片補充細節，讓它們隨時可以接手。也叫 backlog grooming。","also":["待辦清單梳理","Backlog 梳理","需求梳理","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"衝刺審查會議","text":"衝刺結束時的會議，團隊展示完成的東西，聽取大家的想法，以決定接下來做什麼。","also":["衝刺審查會議","衝刺審查","sprint reviews"]},{"id":"demo","g":"agile","word":"展示（Demo）","text":"把完成的工作即時運作起來，展示給提出需求的人看。","also":["展示","示範","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"時間盒","text":"給某件事設定的一段固定時間。時間一到就停下來，即使沒有全部做完。","also":["時間盒","限時","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"速度（Velocity）","text":"團隊在一次衝刺裡通常能完成多少工作，用來計畫下次接多少。它不是衡量大家多努力的分數。","also":["速度","團隊速度","team velocity"]},{"id":"capacity","g":"agile","word":"產能","text":"扣除假期和其他工作之後，團隊在一段時間內能接下多少工作。","noTip":1},{"id":"burndown","g":"agile","word":"燃盡圖","text":"顯示一次衝刺裡剩餘工作逐日下降的圖。如果線一直是平的，就表示有東西卡住了。","also":["燃盡圖","burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"燃起圖","text":"顯示已完成的工作隨時間上升的圖，旁邊是計畫的總量，讓你看出什麼時候能做完。","also":["燃起圖","burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"看板","text":"就是這塊看板本身：工作的每個階段一欄，卡片在各欄之間移動。","also":["看板","Kanban 看板","Kanban boards"]},{"id":"pullsys","g":"agile","word":"拉動式系統","text":"一種工作方式：只有當有人騰出手來時才開始新工作，而不是把工作硬塞給已經滿檔的人。","also":["拉動式系統","拉式","pull-based"]},{"id":"flow","g":"agile","word":"流動","text":"工作在看板上移動得有多順暢。流動良好，就是卡片不斷向前，而不是堆積起來。","also":["流動","工作流動","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"前置時間","text":"從有人提出需求到它完成，一共要多長時間。","also":["前置時間","交付週期","lead times"]},{"id":"cycletime","g":"agile","word":"週期時間","text":"一張卡片從真正開始動工到完成要多長時間。","also":["週期時間","循環時間","cycle times"]},{"id":"throughput","g":"agile","word":"產出量","text":"一週內（或任何固定時間內）完成了多少張卡片。","also":["產出量","吞吐量","throughput rate"]},{"id":"bottleneck","g":"agile","word":"瓶頸","text":"工作堆積、拖慢後面一切的那個環節，就像瓶子細細的瓶頸。","also":["瓶頸","bottlenecks"]},{"id":"swimlane","g":"agile","word":"泳道","text":"看板上橫貫的一列，把同一類卡片歸在一起，例如緊急的工作或某個團隊的卡片。","also":["泳道","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"精實（Lean）","text":"一種工作方式：去掉浪費（任何對客戶沒有幫助的東西），讓工作持續流動。"},{"id":"waste","g":"agile","word":"浪費","text":"在精實裡，指任何要花力氣、卻對客戶沒有幫助的事，例如等待、重工，或做出沒人用的東西。","noTip":1},{"id":"kaizen","g":"agile","word":"持續改善","text":"透過經常做一些小的改動、再檢查是否有幫助，讓自己一點一點不斷變好。回顧會議就是其中一種方法。也叫 kaizen（改善）。","also":["持續改善","改善","kaizen"]},{"id":"selforg","g":"agile","word":"自我組織團隊","text":"自己決定怎麼做事的團隊，而不是被人一步一步告知該怎麼做。","also":["自我組織團隊","自組織","自我管理團隊","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"跨職能團隊","text":"擁有完成工作所需的全部技能的團隊，例如設計、開發和測試，自己就能做完。","also":["跨職能團隊","跨職能","cross-functional"]},{"id":"spike","g":"agile","word":"探針任務（Spike）","text":"一小段限時的調查，在投入真正的工作之前，先回答一個問題。","also":["探針任務","探究任務","spikes"]},{"id":"rework","g":"agile","word":"重工","text":"因為第一次沒做對，所以把工作再做一遍。","also":["重工","返工","重做","reworked"]},{"id":"safe","g":"agile","word":"規模化敏捷（SAFe）","text":"在大型組織裡讓許多團隊一起用敏捷的方法。SAFe（規模化敏捷框架）就是其中一個著名的例子。","also":["規模化敏捷","scaled Agile"]},{"id":"repo","g":"build","word":"儲存庫","text":"專案的程式碼資料夾，附帶完整的 commit 歷史。它可以放在你的電腦上、GitHub 上，或者兩邊都有。","also":["repository","Repo","repo"]},{"id":"branch","g":"build","word":"分支","text":"程式碼中一條獨立的工作線，這樣就能在不動主版本的情況下做變更。","also":["branches","Branch"]},{"id":"commit","g":"build","word":"Commit","text":"程式碼的一次已儲存快照，附有一句變更說明。你隨時可以回到某一個快照。","also":["commits","提交"]},{"id":"push","g":"build","word":"Push","text":"把你儲存好的快照（commit）從這台電腦傳送到線上的共享副本（例如 GitHub），這樣它們有了備份，別人也能取得。"},{"id":"merge","g":"build","word":"合併","text":"把一個分支的變更併入另一個分支，通常是併回主版本。"},{"id":"pr","g":"build","word":"Pull Request","text":"請求把一個分支的變更經過檢查後合併到主版本。有些網站把它叫作合併請求。","also":["PR","PRs","合併請求","merge request"]},{"id":"refactor","g":"build","word":"重構","text":"在不改變功能的前提下整理程式碼：檔案更小、命名更清楚、重複更少。"},{"id":"bug","g":"build","word":"Bug","text":"某樣東西沒有照預期正常運作。","also":["bugs","錯誤"]},{"id":"peerreview","g":"build","word":"同儕審查","text":"多一雙眼睛：由作者以外的人在成果送到你手上之前先檢查，這樣漏網的錯誤會更少。在 AI-gile 裡，每張卡片由另一個 AI 來檢查。","also":["程式碼審查","peer review","code review"]},{"id":"code","g":"build","word":"程式碼","text":"告訴電腦要做什麼的書面指令。也叫原始碼。","also":["程式碼","原始碼","source code"],"noTip":1},{"id":"proglang","g":"build","word":"程式語言","text":"用來寫程式碼的語言，例如 JavaScript、Python 或 Java。不同的語言適合不同的工作。","also":["程式語言","programming languages"]},{"id":"developer","g":"build","word":"開發者（dev）","text":"撰寫和修改程式碼的人。也叫程式設計師或軟體工程師。","also":["開發者","開發人員","程式設計師","軟體工程師","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"軟體","text":"在電腦和手機上執行的程式，與機器本身（硬體）相對。","noTip":1},{"id":"app","g":"build","word":"應用程式（App）","text":"application 的簡稱：人們用來完成某件事的程式，在手機、電腦或網頁瀏覽器裡都有。","also":["應用程式","App","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"網頁應用程式","text":"在網頁瀏覽器裡執行的應用程式，所以不需要安裝任何東西。","also":["網頁應用程式","Web 應用程式","web apps","web application"]},{"id":"frontend","g":"build","word":"前端","text":"應用程式中你能看到並點擊的部分：畫面、按鈕和文字，通常就在你的瀏覽器裡。","also":["前端","front-end","frontend"]},{"id":"backend","g":"build","word":"後端","text":"應用程式在幕後的那一部分，儲存資料，並在你點擊某樣東西時做事，例如核對你的密碼。","also":["後端","back-end","backend"]},{"id":"fullstack","g":"build","word":"全端","text":"前端和後端都能做。","also":["全端","full-stack"]},{"id":"ui","g":"build","word":"使用者介面（UI）","text":"一個人在螢幕上看到並使用的東西：版面、按鈕、選單和文字。","also":["UI","使用者介面","user interface"]},{"id":"ux","g":"build","word":"使用者體驗（UX）","text":"使用某樣東西的感受：輕鬆、清楚、愉快，還是混亂又緩慢。","also":["UX","使用者體驗","user experience"]},{"id":"accessibility","g":"build","word":"無障礙（a11y）","text":"讓所有人都能使用，包括視力不好、無法使用滑鼠或使用螢幕閱讀器的人。","also":["無障礙","輔助功能","a11y"]},{"id":"responsive","g":"build","word":"響應式設計","text":"讓頁面適合各種螢幕尺寸、從手機到大螢幕都好用。","also":["響應式設計","回應式設計"]},{"id":"designsys","g":"build","word":"設計系統","text":"一套共用的顏色、字型、按鈕和規則，讓每個畫面看起來和用起來都是一個樣。","also":["設計系統","design systems"]},{"id":"architecture","g":"build","word":"架構","text":"一個系統的整體形態：主要有哪些部分，以及它們怎樣互相溝通。"},{"id":"database","g":"build","word":"資料庫（DB）","text":"有條理地存放資訊的地方，就像一張非常強大的試算表，應用程式可以讀取和修改它。","also":["資料庫","database","databases","DB"]},{"id":"schema","g":"build","word":"資料庫結構（Schema）","text":"資料庫的配置：它有哪些資料表，每張表裡放什麼。","also":["資料庫結構","綱要","schema"]},{"id":"sql","g":"build","word":"SQL","text":"結構化查詢語言（structured query language）的縮寫：許多資料庫都用它來查詢資料或修改資料。","also":["結構化查詢語言","Structured Query Language"]},{"id":"data","g":"build","word":"資料","text":"電腦儲存的資訊，例如姓名、訂單或設定。","also":["資料","數據","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"伺服器","text":"一直開著、回應其他電腦請求的電腦，例如你造訪網頁時把網頁傳給你。","also":["伺服器","servers"]},{"id":"client","g":"build","word":"用戶端","text":"提出請求的一方，通常是你的瀏覽器或應用程式，去和伺服器溝通。在商業上，它也單純指客戶。","also":["用戶端","客戶端","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"應用程式介面（application programming interface）的縮寫：一份固定的「菜單」，列出一個程式可以向另一個程式提出哪些請求，就像向天氣服務詢問今天的預報。","also":["APIs","應用程式介面","application programming interface"]},{"id":"endpoint","g":"build","word":"端點","text":"API 菜單上的一項：程式可以呼叫的一個網址，用來取得或傳送某樣東西。","also":["端點","endpoints"]},{"id":"integration","g":"build","word":"整合","text":"把兩個系統連起來讓它們一起運作，例如你的網路商店把訂單傳送到你的會計軟體。","also":["整合","串接","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"某件事一發生，一個系統就自動傳給另一個系統的訊息，例如「已收到付款」。","also":["網路鉤子","webhooks"]},{"id":"library","g":"build","word":"函式庫（Library）","text":"別人寫好的現成程式碼，你可以直接重複使用，而不用自己寫。","also":["函式庫","程式庫","libraries"],"noTip":1},{"id":"framework","g":"build","word":"框架","text":"用來開發應用程式的現成結構，決定了程式碼大部分的組織方式，就像一棟房子的骨架，由你來填滿內容。","also":["框架","frameworks"]},{"id":"sdk","g":"build","word":"軟體開發套件（SDK）","text":"一整套工具、程式碼和範例，用來為某個平台或服務開發軟體。","also":["SDK","SDKs","軟體開發套件"]},{"id":"softdep","g":"build","word":"軟體相依套件","text":"你的程式碼要運作所需要的函式庫或工具。為了安全，讓它們保持最新版本很重要。","also":["軟體相依套件","軟體相依性","software dependencies"]},{"id":"package","g":"build","word":"套件","text":"一包現成的程式碼，你可以安裝並用在專案裡。","also":["套件","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"套件管理工具","text":"幫你取得並更新程式碼所依賴的套件的工具。npm 是常見的一個。","also":["套件管理工具","套件管理員","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"最廣泛使用的程式碼歷史紀錄工具，以 commit 和分支的形式保存每一次變更。"},{"id":"github","g":"build","word":"GitHub","text":"一個在線上保存 Git 儲存庫的網站，讓團隊可以共享程式碼、審查變更和追蹤工作。"},{"id":"vcs","g":"build","word":"版本控制","text":"保留檔案每一次變更的完整歷史，讓你看到誰改了什麼，需要時可以退回去。Git 就是這樣做的。","also":["版本控制","原始碼控制","source control","version control system"]},{"id":"clone","g":"build","word":"複製（Clone）","text":"在你自己的電腦上，做一份包含歷史紀錄的儲存庫完整副本。","also":["複製","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"拉取（Pull）","text":"把共享副本（例如 GitHub）上最新的 commit 下載到你的電腦上。與 Push 相反。","also":["拉取","pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"主分支","text":"大家都以它為基礎工作的正式版本程式碼，通常叫 main 或 master。","also":["主分支","main 分支","master branch"]},{"id":"conflict","g":"build","word":"合併衝突","text":"兩處變更以不同的方式改了同樣的幾行，電腦無法把它們合起來，必須由人來選擇。","also":["合併衝突","衝突","merge conflicts"]},{"id":"diff","g":"build","word":"差異（Diff）","text":"一個檢視畫面，精確顯示兩個版本之間改了什麼：新增了哪些行，去掉了哪些行。","also":["差異","diff","diffs"]},{"id":"fork","g":"build","word":"分叉（Fork）","text":"別人儲存庫的一份你自己的副本，你可以隨意修改，而不會影響原本的儲存庫。","also":["分叉","fork","forks","forked"]},{"id":"script","g":"build","word":"腳本","text":"一小段能自己完成一件事的程式，例如整理檔案或啟動應用程式。","also":["腳本","指令碼","scripts"],"noTip":1},{"id":"build","g":"build","word":"建置","text":"把程式碼變成可以執行的東西，或者指變出來的這個可執行成品。","also":["建置","builds"],"noTip":1},{"id":"compile","g":"build","word":"編譯","text":"把人寫的程式碼翻譯成電腦可以直接執行的形式。","also":["編譯","編譯器","compiler"]},{"id":"cli","g":"build","word":"命令列（CLI）","text":"一個文字視窗，你在裡面輸入指令讓電腦執行，而不是用滑鼠點擊。也叫終端機。","also":["命令列","CLI","終端機","command line","command-line","terminal"]},{"id":"config","g":"build","word":"設定（config）","text":"控制軟體行為的各項設定，與程式碼分開存放，方便修改。","also":["設定","組態","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"環境變數","text":"程式啟動時交給它的一項設定，常用來放位址或密碼，這樣它們就不用寫進程式碼裡。","also":["環境變數","environment variables","env var"]},{"id":"debugging","g":"build","word":"除錯（Debug）","text":"找出某樣東西為什麼不能用，並把它修好。","also":["除錯","偵錯","debug","debugged"]},{"id":"pairing","g":"build","word":"結對程式設計","text":"兩個人（或一個人加一個 AI）一起處理同一份程式碼，一個人打字，另一個人檢查。","also":["結對程式設計","配對程式設計","pairing"]},{"id":"docs","g":"build","word":"文件（docs）","text":"書面的說明，講清楚某樣東西是怎麼運作的或怎麼使用。","also":["文件","說明文件","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"儲存庫裡最先該讀的檔案：這個專案是什麼，以及怎麼讓它跑起來。","also":["README","讀我檔案","READMEs"]},{"id":"legacy","g":"build","word":"舊有系統","text":"仍在使用、卻很難修改的老系統，往往因為還懂它的人已經不多。","also":["舊有系統","遺留系統","舊系統","舊程式碼","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"技術債","text":"現在省時間、日後卻讓修改變慢的捷徑，就像會不斷累積利息的貸款。重構就是在還債。","also":["技術債","技術負債","tech debt"]},{"id":"test","g":"test","word":"測試","text":"檢查某樣東西是否依應有的方式運作。有些測試由電腦在程式碼每次變動時自動執行；有些是你在接受之前親自試用做好的卡片。","also":["tests","Test"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"品質保證（quality assurance）的縮寫：為確保工作在上線前是正確的所做的一切。在 AI-gile 裡指的是自動檢查：QA 為紅色就表示有東西沒通過，修好之前不能上線。","also":["品質檢查","品質保證","quality assurance","quality checks"]},{"id":"testpile","g":"test","word":"測試堆疊","text":"等你來試的已完成卡片，一張接一張。接受一張，或附上說明退回去，下一張就會出來。","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"自動化測試","text":"每次程式碼變動時電腦自動執行的檢查，用來及早發現錯誤。","also":["自動化測試","自動測試","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"手動測試","text":"由人親手試用成果，看它的表現是否符合預期。","also":["手動測試","人工測試","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"單元測試","text":"對一小段程式碼單獨做的小型自動檢查。","also":["單元測試","unit tests"]},{"id":"integtest","g":"test","word":"整合測試","text":"檢查多個部分合在一起是否正常運作，而不是一個一個地檢查。","also":["整合測試","integration tests"]},{"id":"endtoend","g":"test","word":"端對端測試（E2E）","text":"像真實使用者一樣從頭到尾走一遍的測試，例如註冊、購買、付款。","also":["E2E","端對端","端對端測試","end-to-end tests"]},{"id":"uat","g":"test","word":"使用者驗收測試（UAT）","text":"由提出需求的人親自試用，並說明它是否滿足他們的需求。AI-gile 的測試堆疊就是它的對應做法。","also":["UAT","驗收測試","acceptance testing"]},{"id":"regression","g":"test","word":"迴歸","text":"原本能用、改動之後卻壞掉的東西。迴歸測試就是檢查舊功能是否仍然正常。","also":["迴歸","迴歸測試","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"冒煙測試","text":"非常快速的檢查，看主要功能到底能不能用，例如剛上線一項變更之後。如果沒通過，就先停下來查看。","also":["冒煙測試","煙霧測試","smoke tests"]},{"id":"exploratory","g":"test","word":"探索式測試","text":"自由地使用產品，用各種方式去摸索，找出事先設計好的檢查發現不了的問題。","also":["探索式測試","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"測試案例","text":"一個寫好的測試情境：要執行的步驟，以及應該出現什麼結果。","also":["測試案例","測試用例","test cases"]},{"id":"coverage","g":"test","word":"測試覆蓋率","text":"有多少程式碼被自動測試檢查過。通常越高越保險，但光有高覆蓋率並不能證明它運作得好。","also":["覆蓋率","程式碼覆蓋率","code coverage"]},{"id":"testdata","g":"test","word":"測試資料","text":"測試時使用的虛構範例資訊，這樣就不會洩露任何真人的私人資料。","also":["測試資料","test fixtures"]},{"id":"edgecase","g":"test","word":"邊界情況","text":"處於極限的特殊情形，例如空白的表單或帶撇號的名字，這類地方常常出問題。","also":["邊界情況","邊緣案例","edge cases"]},{"id":"happypath","g":"test","word":"理想路徑（Happy path）","text":"一切順利的正常流程。好的測試也會試一試不順利的路徑。"},{"id":"perftest","g":"test","word":"效能測試","text":"檢查某樣東西有多快，以及在壓力下撐得怎麼樣。","also":["效能測試","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"負載測試","text":"檢查很多人同時使用時，系統能否應付得來。","also":["負載測試","壓力測試","load test","load tests"]},{"id":"sectest","g":"test","word":"安全測試","text":"尋找可能被人濫用系統、或看到不該看的內容的漏洞。","also":["安全測試","security test","security tests"]},{"id":"accesstest","g":"test","word":"無障礙測試","text":"檢查能力各不相同的人是否都能使用產品，包括使用螢幕閱讀器或只用鍵盤的人。","also":["無障礙測試","輔助功能測試","accessibility test"]},{"id":"linting","g":"test","word":"程式碼檢查（Lint）","text":"自動檢查，找出程式碼裡可能的錯誤和雜亂的寫法，就像程式的拼字檢查。","also":["程式碼檢查","linter","lint"]},{"id":"static","g":"test","word":"靜態分析","text":"不執行程式碼，而是讓電腦自動閱讀程式碼來找出問題。","also":["靜態分析","靜態程式碼分析","static code analysis"]},{"id":"flaky","g":"test","word":"不穩定測試","text":"有時通過、有時失敗，又說不清原因的測試，所以不能完全信任它。","also":["不穩定測試","flaky tests"]},{"id":"repro","g":"test","word":"重現","text":"照著同樣的步驟讓 bug 故意再出現一次，這樣才能研究並修好它。把這些步驟寫下來，是 bug 回報裡最有用的部分。","also":["重現","重現步驟","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"嚴重程度","text":"一個問題造成的影響有多糟，從小小的麻煩到一切停擺。","also":["嚴重程度","嚴重性","severity level"]},{"id":"deploy","g":"change","word":"部署","text":"把軟體的新版本複製到執行它的電腦上，例如測試副本或正式上線的服務。"},{"id":"release","g":"change","word":"發行版本","text":"一批有名稱、一起上線的已完成工作，附上幾句簡短說明，講清楚改了什麼。🚀 發行版本 會根據已完成的卡片寫好這些說明。","also":["發布","發行","release","releases"]},{"id":"rollback","g":"change","word":"回滾","text":"新版本出問題時，退回到上一個正常的版本。在 AI-gile 裡，「回滾」會把每項變更上寫好的復原步驟彙整成一份清單。","also":["回復上一版","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"正式環境","text":"大家真正在用的那個版本，而不是拿來試東西的副本。把東西放上去就叫上線。開發者也叫它 production。","also":["上線","線上","production","live"],"noTip":1},{"id":"change","g":"change","word":"變更","text":"對大家依賴的東西所做的有計畫的修改，事先寫清楚：改什麼、為什麼、有什麼風險、什麼時候改、怎麼復原。用 🔀 提出變更 來開始。","also":["變更請求","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"風險","text":"可能出錯的事，依發生的可能性和嚴重程度評分。⚠️ 風險 把它們放在同一個清單裡，分數最高的在最前面，每一項都有再次檢視的日期。","also":["風險登記","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"變更時段","text":"允許變更上線的時間，例如一個清閒的星期二晚上。在時段之外，變更卡片無法完成，除非是緊急狀況。","also":["變更窗口","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"變更上線前的最後檢查：每位需要核准的人都要說 Go 或 No go。只有所有人都說 Go 才會繼續。","also":["go/no go","go-no-go","上線決策"]},{"id":"approval","g":"change","word":"核准","text":"開工前先等一聲「好」。朋友提出的卡片，或一項變更，會在 ✅ 核准 裡等著，直到你核准或拒絕。","also":["批准","審核","approval","approvals"]},{"id":"quiettime","g":"change","word":"安靜時段","text":"一段什麼都不上線的時間，例如直播、展示期間或夜間。團隊照常工作和測試，但上線要等到這段時間結束。在其他地方叫作「變更凍結」。","also":["變更凍結","封版","quiet time","quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"一種工作方式：開發軟體的人和維運軟體的人組成一個團隊，大量使用自動化，讓變更可以經常、安全地上線。"},{"id":"cicd","g":"change","word":"CI/CD（持續整合與持續交付）","text":"大家的變更經常合併到主版本裡，而且每次都會自動檢查（持續整合），所以軟體隨時都能一鍵上線（持續交付）。","also":["CI/CD","CI","CD","持續整合","持續交付","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"持續部署","text":"比持續交付更進一步：每項通過檢查的變更都會自動上線，不需要按任何按鈕。","also":["持續部署","continuous deployments"]},{"id":"pipeline","g":"change","word":"管線（Pipeline）","text":"一項變更在上線的路上要經過的一連串自動步驟，例如建置、測試，然後部署。","also":["管線","流水線","pipelines"]},{"id":"environment","g":"change","word":"環境","text":"為某個用途單獨準備的一份系統副本，例如一份用來開發、一份用來測試，還有一份是正式上線的。","also":["環境","environments"],"noTip":1},{"id":"devenv","g":"change","word":"開發環境","text":"開發者工作用的那份副本，通常在自己的電腦上，在這裡弄壞了東西也不會傷到任何人。","also":["開發環境","dev environment"]},{"id":"testenv","g":"change","word":"測試環境","text":"專門用來測試的一份獨立系統副本，不會碰到真正的服務。","also":["測試環境","test environments"]},{"id":"staging","g":"change","word":"預備環境（Staging）","text":"依正式環境的樣子建好的最後一份副本，在變更上線前做最後檢查。","also":["預備環境","預發布環境","staging environment"]},{"id":"artifact","g":"change","word":"建置產物","text":"一次建置產出的檔案或檔案包，可以用來存放、檢查或上線。","also":["建置產物","build artifacts"]},{"id":"hotfix","g":"change","word":"緊急修復（Hotfix）","text":"因為重要的東西壞了，繞開正常計畫、很快上線的緊急修復。","also":["緊急修復","熱修復","hotfixes"]},{"id":"patch","g":"change","word":"修補程式","text":"修復 bug 或堵住安全漏洞的小更新。盡快安裝安全性修補很重要。","also":["修補程式","補丁","patches","security patch","security patches","安全性修補"]},{"id":"version","g":"change","word":"版本號碼","text":"像 2.4.1 這樣的標籤，說明你用的是哪個版本。通常第一個數字在大改動時變化，最後一個數字在小修復時變化。","also":["版本號碼","版本號","語意化版本","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"發行說明","text":"用簡單的話列出一個版本裡改了什麼，寫給使用者看，包括修復的問題和已知的限制。也叫更新日誌。","also":["發行說明","更新日誌","changelog","change log"]},{"id":"flag","g":"change","word":"功能開關","text":"功能的開關：新做的東西可以先隱藏著上線，之後再打開（或再關掉），不需要發行新版本。","also":["功能開關","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"向前修復","text":"遇到有問題的版本時，不是退回舊版本，而是盡快發行一個修正後的新版本來修復。","also":["向前修復","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"金絲雀發布","text":"先讓一小部分人用上變更，看起來沒問題再給所有人。名字來自礦工帶到井下當預警的金絲雀。","also":["金絲雀發布","灰度發布","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"藍綠部署","text":"保留兩份正式系統，一次把大家切換到新的那份，萬一出問題，可以馬上切回去。","also":["藍綠部署","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"零停機部署","text":"讓新版本上線，而服務始終不會對使用者中斷。","also":["零停機部署","零停機","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"變更管理","text":"幫助變更順利成功：權衡風險、取得適當的核准，並選一個合適的時間。","also":["變更管理","變更賦能","change management"]},{"id":"cab","g":"change","word":"變更諮詢委員會（CAB）","text":"審查重要變更、並決定是否以及何時可以進行的小組。","also":["CAB","變更委員會"]},{"id":"stdchange","g":"change","word":"標準變更","text":"風險低、每次都用同樣成熟做法完成的變更，所以事先就已經核准。","also":["標準變更","standard changes"]},{"id":"normchange","g":"change","word":"一般變更","text":"需要先檢查並獲得核准才能進行的變更。","also":["一般變更","普通變更","normal changes"]},{"id":"emergchange","g":"change","word":"緊急變更","text":"必須馬上進行以修復或避免嚴重問題的變更，核准也相應更快。","also":["緊急變更","emergency changes"]},{"id":"automation","g":"change","word":"自動化","text":"讓電腦自己完成重複的工作，這樣更快，而且每次做法都一致。","also":["自動化","automated"],"noTip":1},{"id":"infra","g":"change","word":"基礎設施","text":"軟體執行所依靠的機器、網路和服務。","also":["基礎設施","基礎架構","infra"]},{"id":"iac","g":"change","word":"基礎設施即程式碼（IaC）","text":"把伺服器和設定寫在跟程式碼放在一起的檔案裡，這樣每次都能原樣重建出來。","also":["IaC","基礎設施即程式碼"]},{"id":"cloud","g":"change","word":"雲端","text":"透過網際網路向大型供應商租用電腦、儲存空間和服務，而不是自己擁有這些機器。","also":["雲端","雲","雲端運算","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"雲端服務供應商","text":"透過網際網路出租運算資源的公司，例如亞馬遜雲端服務（AWS）、微軟 Azure 或 Google Cloud。","also":["雲端服務供應商","雲端供應商","cloud providers"]},{"id":"hosting","g":"change","word":"代管","text":"你的應用程式或網站存放和執行的地方，讓人們可以連上，通常是向某家公司租用的。","also":["代管","主機代管","虛擬主機"]},{"id":"domain","g":"change","word":"網域名稱","text":"人們輸入的網址，例如 example.com。網域按年租用，所以必須續約。","also":["網域名稱","網域","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"網域名稱系統的縮寫：網際網路的通訊錄，把 example.com 這樣的名字換成正確那台電腦的位址。","also":["網域名稱系統","domain name system"]},{"id":"container","g":"change","word":"容器","text":"一個密封的包，裡面裝著應用程式和它需要的一切，所以在任何電腦上執行起來都一樣。最有名的工具是 Docker。","also":["容器","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"虛擬機器（VM）","text":"在一台真實電腦裡執行的「假電腦」，所以一台大機器可以當成很多台來用。","also":["VM","VMs","虛擬機器","virtual machines"]},{"id":"serverless","g":"change","word":"無伺服器（Serverless）","text":"執行程式碼卻不用自己管任何伺服器：需要時由供應商來執行，用多少付多少。"},{"id":"lb","g":"change","word":"負載平衡器","text":"把訪客分散到好幾台伺服器上的東西，這樣沒有哪一台會被壓垮。","also":["負載平衡器","負載平衡","load balancers"]},{"id":"cache","g":"change","word":"快取","text":"把最近的結果放在手邊的便利儲存空間，這樣同樣的東西不用再去取或再算一遍。清除快取有時能解決頁面顯示過時內容的問題。","also":["快取","caches","caching","cached"]},{"id":"cdn","g":"change","word":"內容傳遞網路（CDN）","text":"遍布全球的一批伺服器，在你的訪客附近存放你的頁面和圖片副本，讓它們很快載入。","also":["CDN","內容傳遞網路"]},{"id":"migration","g":"change","word":"遷移","text":"把資料或系統從舊的配置搬到新的，或者小心地改變資料庫的結構。","also":["遷移","資料遷移","migrations","database migration"]},{"id":"service","g":"run","word":"服務","text":"你做出來、大家依賴的東西，例如網站或 App，有人照顧著讓它持續正常運作。勾選「此專案是一項服務」，再寫上它提供什麼、誰在用、誰值班。","also":["service","services"]},{"id":"uptimepct","g":"run","word":"正常運作時間","text":"一項服務有多少時間在正常運作，通常用百分比表示。99.9% 仍然允許每月停機大約 43 分鐘。","also":["正常運作時間","可用時間","uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"可用性檢查","text":"每隔幾分鐘自動檢查一次你的服務是否還有回應。如果連續失敗幾次，AI-gile 會自己開一張事故卡片。","also":["可用性檢查","uptime checks"]},{"id":"statuspage","g":"run","word":"狀態頁","text":"一個公開頁面，顯示服務是否正常（綠、橘或紅）以及最新進度，讓使用者自己查看，不必來問。","also":["狀態頁面","status page","status pages"]},{"id":"desk","g":"run","word":"服務台","text":"使用你服務的人提出的問題和回報都會送到這裡。AI-gile 會把每一則分類為請求、事故或想法，如果看起來跟已經回報過的東西很像，也會告訴你。","also":["服務台","客服台","help desk","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"服務請求","text":"有人要的是一般的東西，例如新帳號或一點協助，而不是回報有東西壞了。它會排隊等候；事故優先處理。","also":["服務請求","請求","service request","service requests"]},{"id":"incident","g":"run","word":"事故","text":"現在對使用者來說壞了或不能正常運作的東西，例如網站掛了或非常慢。🔥 事故卡片會插隊：先讓它恢復正常。","also":["故障","incident","incidents"]},{"id":"major","g":"run","word":"重大事故","text":"大型事故：影響很多人，或金錢或資料有危險。一個按鈕就能讓所有團隊投入（蜂群），叫醒值班的人，並要求每 30 分鐘更新一次狀態。","also":["重大事件","major incident","major incidents"]},{"id":"oncall","g":"run","word":"值班","text":"就是出問題時負責回應的人，就算是半夜。每項服務都有一位值班的團隊成員，它的事故會最先叫醒這個人。","also":["值班人員","待命","on call","on-call"]},{"id":"replyby","g":"run","word":"回覆期限","text":"一張卡片最多能等多久得到第一次回覆，例如事故是一小時。超過之後它會出現紅色時鐘，免得有事被悄悄遺忘。也叫回應目標。","also":["回應目標","回應時間","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"事後檢討","text":"事故之後的簡短回顧：發生了什麼、什麼有幫助、要改什麼，不追究任何人的責任。沒有事後檢討，事故就不能關閉。","also":["事故檢討","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"問題","text":"一個或多個事故背後的隱藏原因。🧩 問題卡片會把反覆出現的事故歸在一起，好找出原因並徹底修好。","also":["problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"根本原因","text":"東西壞掉的真正原因，而不只是你看到的表面故障。修好根本原因，事故就不會再回來。","also":["根因","root cause","root causes"]},{"id":"workaround","g":"run","word":"暫時解決辦法","text":"在真正的修正完成前讓東西繼續運作的辦法，例如卡住時重新啟動一下。它會寫在問題卡片上，這樣誰都不用再摸索一次。","also":["暫時方案","權宜之計","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"已知錯誤","text":"原因已經搞清楚、也有暫時的解決辦法，但還沒修好的問題。「🧩 已知錯誤」會把它們列出來，大家直接用暫時的解決辦法，不用再重新排查。","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"操作手冊","text":"處理某類已知問題的逐步說明，讓每次都用同樣的方式快速搞定。重大事故之後，團隊可以擬一份操作手冊，交給你確認。","also":["Runbook","runbooks","運行手冊"]},{"id":"ci","g":"run","word":"設定項目","text":"你的服務所依賴的某樣東西，例如伺服器、網域、憑證、金鑰或供應商。🗂️ 設定項目會按服務列出它們，讓你看出事故會影響到什麼，以及哪些東西需要續期或備份。","also":["設定項目","組態項目","configuration item","configuration items","CI"]},{"id":"expiry","g":"run","word":"到期日","text":"某樣東西不更新就會失效的日期，例如網站的安全憑證或網址。AI-gile 會盯著這些日期，並在到期前 30 天為每一項建一張更新卡片，這樣什麼都不會突然失效。","also":["到期日","到期","到期提醒","expiry date","expiry dates","expiry"]},{"id":"backup","g":"run","word":"備份","text":"你的資料之前存下來的一份副本，萬一有東西遺失或損壞可以靠它。AI-gile 每天都會備份你的看板。","also":["backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"還原","text":"從備份把資料放回去。只有確定能還原，備份才算真的有用，所以值得偶爾試一下。","also":["復原","已還原","restore","restored"]},{"id":"svcreview","g":"run","word":"服務回顧","text":"回頭看一項服務的一個月：開啟和修好的事故、大家多快得到回覆、正常運作時間，以及用掉的 token。月度檢討會為每項服務顯示這些內容。","also":["服務回顧","月度檢討","每月回顧","service review","monthly review"]},{"id":"accessreview","g":"run","word":"存取審查","text":"每 90 天檢查一次誰還能進來：分享連結、朋友的角色，以及儲存的密碼和金鑰。每一項由你決定保留或移除，這樣舊的存取權限不會一直留著。","also":["存取審查","權限審查","access review","access reviews"]},{"id":"improvements","g":"run","word":"改進清單","text":"團隊決定要做得更好的所有事情，集中在一個地方：回顧會議的建議、檢討的行動項目和問題的修正，每一項都附上狀態。到 📈 改進 裡就能找到。","also":["改進清單","改進","improvement list","improvements"]},{"id":"tokencap","g":"run","word":"Token 上限","text":"一項服務的代理每月可用 token 的上限。到 80% 時你會收到警告；到 100% 時，它們的背景工作會等到下個月，或等你調高上限。","also":["token 上限","每月 token 上限","token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"服務管理","text":"為了讓一項服務日復一日地對依賴它的人保持有用、正常運作所做的一切。","also":["服務管理"]},{"id":"itil","g":"run","word":"ITIL","text":"一套廣泛使用的優良服務管理指南，涵蓋事故、問題和變更等內容。這個名字原本是 IT 基礎架構庫（IT Infrastructure Library）的縮寫。"},{"id":"itsm","g":"run","word":"IT 服務管理（ITSM）","text":"把科技當作一項為人提供的服務來營運，用清楚的方式處理請求、事故、變更和改進。","also":["ITSM","IT 服務管理"]},{"id":"managed","g":"run","word":"託管服務","text":"由別人替你營運和維護的服務，並依協議保證它要達到的水準。","also":["託管服務","代管服務","managed services"]},{"id":"svcowner","g":"run","word":"服務負責人","text":"為整項服務負責的人：它運作得怎麼樣、花多少錢、怎樣改進。","also":["服務負責人","服務擁有者","service owners"]},{"id":"sla","g":"run","word":"服務水準協議（SLA）","text":"對客戶做出的書面承諾，說明服務會達到什麼水準，例如「99.9% 的時間可用」或「一小時內回覆」，沒做到時往往要退款。","also":["SLA","SLAs","服務水準協議","service level agreement"]},{"id":"slo","g":"run","word":"服務水準目標（SLO）","text":"團隊自己訂的目標，說明一項服務在一段時間內應該達到什麼水準，通常比 SLA 訂得更嚴一點，以求穩妥。","also":["SLO","SLOs","服務水準目標"]},{"id":"sli","g":"run","word":"服務水準指標（SLI）","text":"拿來和目標對照的實際測量值，例如正常載入的造訪所占的比例。","also":["SLI","SLIs","服務水準指標"]},{"id":"availability","g":"run","word":"可用性","text":"人們需要時能不能用上這項服務，常用正常運作時間來衡量。","also":["可用性","高可用","high availability"]},{"id":"downtime","g":"run","word":"停機時間","text":"服務無法運作或被關掉的時間，無論是計畫內的還是計畫外的。","also":["停機時間","停機","down time"]},{"id":"errorbudget","g":"run","word":"錯誤預算","text":"可靠度目標所允許的那一點點失敗。還有剩餘時，可以對變更冒些風險；用完了，就要放慢腳步。","also":["錯誤預算","error budgets"]},{"id":"outage","g":"run","word":"服務中斷","text":"服務對使用者來說停了或嚴重出毛病的一段時間。","also":["服務中斷","停擺","當機","outages"]},{"id":"degraded","g":"run","word":"服務降級","text":"還能用，但狀態很差：很慢，或者有些部分不能用。","also":["服務降級","效能下降","degraded service"]},{"id":"monitoring","g":"run","word":"監控","text":"隨時自動盯著一項服務，這樣問題能被發現，最好是在使用者察覺之前。","also":["監控","監測"]},{"id":"observability","g":"run","word":"可觀測性","text":"憑系統的日誌、數據和追蹤紀錄，從外面看出裡面發生了什麼的難易程度。","also":["可觀測性","o11y"]},{"id":"log","g":"run","word":"日誌","text":"程式一路記下自己在做什麼的流水帳，用來查出哪裡出了問題。","also":["日誌","紀錄檔","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"追蹤（Trace）","text":"一個請求一步步穿過系統各個部分的紀錄，能看出它在哪裡變慢了。","also":["追蹤","鏈路追蹤","traces","tracing"]},{"id":"latency","g":"run","word":"延遲","text":"得到回應要花多長時間，例如從點擊到頁面出現之間的等待。","also":["時延"]},{"id":"alert","g":"run","word":"警示","text":"自動發出的訊息，告訴你有事需要處理，例如網站沒有回應。","also":["警示","警報","通知","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"警示疲勞","text":"警示多到人們開始不理會，連重要的也一起忽略。","also":["警示疲勞","警報疲勞","alarm fatigue"]},{"id":"dashboard","g":"run","word":"儀表板","text":"一個畫面，讓你一眼看到最重要的數字和狀態。","also":["儀表板","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"呼叫值班人員（Paging）","text":"為了某個問題，緊急打電話給值班的人或把他叫醒。","also":["緊急呼叫","傳呼","paged"]},{"id":"escalation","g":"run","word":"升級通報","text":"當問題在目前這一層解決不了、或解決得不夠快時，請更有本事或更有權限的人來處理。","also":["升級通報","問題升級","escalate","escalated"]},{"id":"triage","g":"run","word":"分流（Triage）","text":"依緊急和重要的程度，快速替收到的問題分類，讓最嚴重的先得到處理。","also":["分流","檢傷分類","triaged"]},{"id":"impact","g":"run","word":"影響範圍","text":"某件事影響人的程度：影響多少人，影響多嚴重。","noTip":1},{"id":"urgency","g":"run","word":"緊急程度","text":"某件事需要多快處理。影響範圍和緊急程度合起來，就決定了優先順序。","noTip":1},{"id":"plevels","g":"run","word":"優先等級（P1、P2…）","text":"表示問題有多緊急的標籤。P1 最嚴重，需要立刻行動。","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"工單佇列","text":"等著有人來接手的請求和事故的清單。","also":["工單佇列","ticket queues"]},{"id":"tiers","g":"run","word":"第一線與第二線","text":"支援的層級：第一線負責接電話、解決簡單的問題；第二線有更深的技能，處理更難的問題。也叫第一層和第二層（tier 1 和 tier 2）。","also":["第一線","第二線","一線支援","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"事故指揮官","text":"帶領大家應對一起事故的那位唯一負責人，這樣每個人都知道誰來拍板、誰做什麼。","also":["事故指揮官","事件指揮官","incident commanders"]},{"id":"responsetime","g":"run","word":"回應時間","text":"從提出一個請求或事故，到有人第一次接手，中間要多久。","also":["回應時間","response times"]},{"id":"resolution","g":"run","word":"解決時間","text":"把一個請求或事故完全處理好要多久，從回報到修好。","also":["解決時間","time to resolve","resolution times"]},{"id":"mttr","g":"run","word":"平均修復時間（MTTR）","text":"平均來說，服務出故障後要花多久才能恢復正常。MTTR 的含義可能略有不同，所以要說明你量的是什麼。","also":["MTTR","平均恢復時間","mean time to restore"]},{"id":"mtbf","g":"run","word":"平均故障間隔時間（MTBF）","text":"平均來說，一項服務運作多久才會出一次問題。","also":["MTBF","平均無故障時間"]},{"id":"cmdb","g":"run","word":"組態管理資料庫（CMDB）","text":"列出你所有組態項目及其相互關係的清單，讓你看出什麼依賴什麼。","also":["CMDB","組態管理庫"]},{"id":"asset","g":"run","word":"資產","text":"你為運作服務而擁有或付費的任何有價值的東西，例如一台筆記型電腦、一份軟體授權或一個網域名稱。","also":["資產","assets"],"noTip":1},{"id":"capplan","g":"run","word":"容量規劃","text":"確保對即將到來的需求，有足夠的運算能力、儲存空間和人手。","also":["容量規劃","capacity plan"]},{"id":"scaling","g":"run","word":"擴充","text":"應對更多使用者的辦法：給一台機器增加效能（垂直擴充），或者增加更多機器（水平擴充）。","also":["擴充","擴展","垂直擴充","水平擴充","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"業務持續運作","text":"當出現大問題（例如失去辦公室、關鍵供應商或所有電腦）時，讓重要的事情繼續運轉的計畫。","also":["業務持續運作","營運持續","business continuity plan"]},{"id":"dr","g":"run","word":"災難復原（DR）","text":"發生嚴重狀況（例如整個資料中心都沒了）之後，把服務恢復回來的計畫和工具。","also":["災難復原","災備","disaster recovery"]},{"id":"rto","g":"run","word":"復原時間目標（RTO）","text":"災難發生後，服務最長可以停多久，之後就必須恢復運作。","also":["RTO","復原時間目標"]},{"id":"rpo","g":"run","word":"復原點目標（RPO）","text":"你能承受損失多少最近的資料，以時間來衡量。RPO 為一小時，就表示至少每小時備份一次。","also":["RPO","復原點目標"]},{"id":"redundancy","g":"run","word":"備援","text":"準備好備用品，例如第二台伺服器，這樣一處故障不會讓服務停擺。","also":["備援","冗餘"]},{"id":"failover","g":"run","word":"故障轉移","text":"平時用的系統出故障時，自動切換到備用系統。","also":["故障轉移","容錯移轉","fail over"]},{"id":"spof","g":"run","word":"單點故障","text":"某個部分一旦壞掉就會連累整體，因為沒有備用的。","also":["單點故障","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"維護時段","text":"為了保養而計畫好的一段時間，服務可能暫停或變慢，會提前通知使用者。","also":["維護時段","計畫維護","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"交接","text":"把工作、知識和責任交給另一個人或團隊，這樣不會有東西被漏掉。","also":["交接","工作交接","handovers"]},{"id":"kb","g":"run","word":"知識庫","text":"一批說明文章和解答的集合，給使用者看，也給團隊看。","also":["知識庫","knowledge bases"]},{"id":"csat","g":"run","word":"客戶滿意度（CSAT）","text":"使用者給出的分數，表示他們有多滿意，通常在請求處理完畢後詢問。","also":["CSAT","滿意度"]},{"id":"supplier","g":"run","word":"供應商","text":"你所依賴的外部公司，例如你的代管服務商。也叫廠商或第三方。","also":["供應商","廠商","第三方","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"服務退役","text":"安全地把一項服務永久關閉：通知它的使用者、處理它的資料和存取權限，並停止它的費用。","also":["服務退役","下線服務","retiring a service"]},{"id":"eol","g":"run","word":"生命週期結束（EOL）","text":"產品不再有廠商提供的更新或支援，所以應該換掉了。","also":["EOL","end-of-life","停止支援"]},{"id":"cybersec","g":"sec","word":"資訊安全","text":"保護系統和資料，不被闖入、竊取或破壞。","also":["資訊安全","網路安全","cyber security"]},{"id":"authn","g":"sec","word":"身分驗證","text":"確認一個人是誰，通常靠密碼或驗證碼。常簡寫為 authn。","also":["身分驗證","身分認證","authn"]},{"id":"authz","g":"sec","word":"授權","text":"在知道對方是誰之後，確認他被允許做什麼。常簡寫為 authz。","also":["授權","權限授予","authz","authorization"]},{"id":"mfa","g":"sec","word":"多重要素驗證（MFA）","text":"用兩種或更多的證明來登入，例如密碼加上手機上的驗證碼。也叫雙重驗證（2FA）。","also":["MFA","2FA","兩步驟驗證","雙重驗證","雙因素驗證","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"單一登入（SSO）","text":"登入一次就能進入很多系統，就像到處都用你的工作帳號。","also":["SSO","單一登入"]},{"id":"pwmgr","g":"sec","word":"密碼管理工具","text":"一個能產生高強度密碼並替你記住它們的應用程式。","also":["密碼管理工具","密碼管理員","password managers"]},{"id":"secret","g":"sec","word":"機密（Secret）","text":"程式用來進入某處的密碼、金鑰或其他私密代碼。絕不能分享，也不能寫進程式碼裡。","also":["機密","金鑰","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API 金鑰","text":"一個保密的代碼，讓程式可以使用另一項服務的 API，並顯示是誰在用（以及誰在付費）。","also":["API 金鑰","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"存取權杖","text":"一張臨時通行證，證明程式被允許進入，這樣不必每次都用你的密碼。它和 AI 的 token 不是一回事。","also":["存取權杖","權杖","access tokens"]},{"id":"encryption","g":"sec","word":"加密","text":"把資訊打亂，只有拿著正確金鑰的人才能讀懂。","also":["加密","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"網頁傳輸的安全方式，瀏覽器裡的小鎖圖示就是標誌，這樣中間沒有人能讀取或竄改。"},{"id":"cert","g":"sec","word":"SSL/TLS 憑證","text":"一張數位身分證，讓網站能證明自己的身分並使用 HTTPS。憑證會過期，所以必須更新。","also":["TLS 憑證","SSL 憑證","憑證","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"權限","text":"規定誰可以檢視或修改什麼的規則。","also":["權限","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"最小權限原則","text":"只給每個人或程式真正需要的存取權限，而且只在需要的時候給。","also":["最小權限","最小特權","principle of least privilege"]},{"id":"rbac","g":"sec","word":"角色型存取控制（RBAC）","text":"依角色（例如檢視者或編輯者）來授予權限，而不是一個人一個人地設定。","also":["RBAC","角色權限控制","role-based access"]},{"id":"vuln","g":"sec","word":"漏洞","text":"別人可能利用來闖入或造成破壞的弱點。","also":["漏洞","安全漏洞","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"零時差漏洞","text":"攻擊者知道、而廠商還沒來得及修復的弱點。","also":["零時差漏洞","零時差","zero-days","zero day"]},{"id":"malware","g":"sec","word":"惡意軟體","text":"有害的軟體，例如病毒，用來破壞、窺探或竊取。","also":["惡意軟體"]},{"id":"ransomware","g":"sec","word":"勒索軟體","text":"把你的檔案鎖起來、要你付錢才解鎖的惡意軟體。做好備份是最好的防禦。","also":["勒索軟體","勒索病毒","ransomware attack"]},{"id":"phishing","g":"sec","word":"網路釣魚","text":"偽造的訊息，想騙你交出密碼或錢，或者打開有害的東西。","also":["網路釣魚","釣魚郵件","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"社交工程","text":"騙的不是電腦而是人，讓人交出存取權限，例如冒充「IT 支援」打來的假電話。"},{"id":"firewall","g":"sec","word":"防火牆","text":"一個守衛，決定哪些網路流量可以進來或出去。","also":["防火牆","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"虛擬私人網路的縮寫：在網際網路上建立的一條私密、加密的連線，常用來安全地連到工作系統。","also":["虛擬私人網路","virtual private network"]},{"id":"ddos","g":"sec","word":"阻斷服務攻擊（DoS、DDoS）","text":"用大量假流量淹沒一項服務，讓真正的人用不了。DDoS 指流量來自許多台電腦同時發出。","also":["DoS","DDoS","阻斷服務","阻斷服務攻擊","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"滲透測試","text":"請友善的專家試著闖進來，這樣在真正的攻擊者發現之前，先找出弱點。","also":["滲透測試","pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"安全稽核","text":"對照一份良好做法的清單，仔細檢查某樣東西保護得怎麼樣。","also":["安全稽核","安全檢查","security audits"]},{"id":"threatmodel","g":"sec","word":"威脅建模","text":"想清楚誰可能攻擊某樣東西、怎麼攻擊，以及你會怎麼阻止他們。","also":["威脅建模","威脅模型","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"資料外洩","text":"私人資訊落到不該拿到的人手裡，或者未經許可就遺失或被改動。","also":["資料外洩","資料洩漏","data breaches"]},{"id":"pii","g":"sec","word":"個人資料","text":"任何關於可識別身分的人的資訊，例如姓名、電子郵件地址或位置。也叫 PII。","also":["個人資料","個資","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"歐洲關於個人資料的法律（英國有自己的版本）：只蒐集需要的、妥善保管，並讓人們可以檢視或刪除自己的資料。","also":["一般資料保護規則","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"資料保護","text":"依法妥善地保管個人資料。","also":["資料保護","資料保護法","data protection law"]},{"id":"privacypolicy","g":"sec","word":"隱私權政策","text":"一個公開的頁面，說明你蒐集哪些個人資料、為什麼蒐集，以及怎麼處理。","also":["隱私權政策","隱私政策","隱私聲明","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"同意","text":"一個人明確、自願地答應：他的資料可以依某種方式使用。他隨時可以收回。","also":["同意","使用者同意","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"網站存放在你瀏覽器裡的小檔案，用來記住一些事情，例如你已登入。有些需要先取得你的同意。","also":["Cookie","cookies","餅乾"],"noTip":1},{"id":"minimisation","g":"sec","word":"資料最小化","text":"只蒐集並保留完成這項工作真正需要的個人資料。","also":["資料最小化","data minimization"]},{"id":"retention","g":"sec","word":"資料保存","text":"資料在被刪除之前保存多久。不超過需要的時間，更安全，往往也是法律要求。","also":["資料保存","保存期限","retention period"]},{"id":"anon","g":"sec","word":"匿名化","text":"改動資料，讓人們再也無法合理地從中認出誰是誰。","also":["匿名化","匿名資料","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"假名化","text":"把姓名和其他細節換成代碼，另外保管一把金鑰用來對應回去。它仍然屬於個人資料。","also":["假名化","化名處理","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"資料處理協議（DPA）","text":"一份合約，規定供應商可以怎樣代你處理個人資料。","also":["DPA","資料處理協議"]},{"id":"dpia","g":"sec","word":"資料保護影響評估（DPIA）","text":"在開始之前，仔細審視使用個人資料的計畫會對人們產生什麼影響，以及如何降低風險。","also":["DPIA","資料保護影響評估"]},{"id":"auditlog","g":"sec","word":"稽核日誌","text":"記錄誰在什麼時候做了什麼，這樣日後可以查核這些操作。","also":["稽核日誌","稽核紀錄","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"法規遵循","text":"遵守適用於你的法律、規則和標準，並且能證明你做到了。","also":["法規遵循","合規","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"管理資訊安全的一項著名國際標準。公司可以申請依它認證。","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"美國的一種報告，由外部稽核人員檢查，證明一家公司妥善地保管客戶資料。","also":["SOC2"]},{"id":"agent","g":"ai","word":"代理程式","text":"獨立處理任務的 AI：讀程式碼、做變更、執行檢查，並回報結果。它的工作仍然會被檢查。","also":["agents","Agent","agent"]},{"id":"token","g":"ai","word":"Token","text":"AI 閱讀和書寫的文字小片段，每個大約相當於四分之三個單字。AI 的用量按 Token 計算，所以用的 Token 越少，你的方案剩得越多。","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"在特定時刻自動執行的小指令，例如 AI 工作階段開始時，這樣團隊就能聽到你的留言。","also":["hooks"]},{"id":"ai","g":"ai","word":"人工智慧（AI）","text":"能做一些我們通常認為需要人才能做的事的電腦系統，例如寫作、回答問題或辨識圖片。","also":["AI","人工智慧","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"機器學習（ML）","text":"讓電腦從大量範例中學會規律的方法，而不是給它精確的規則。","also":["機器學習","machine learning"]},{"id":"model","g":"ai","word":"模型","text":"AI 系統經過訓練的「大腦」，透過學習海量範例而成。不同模型在能力、速度和價格上各不相同。","also":["模型","AI 模型","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"大型語言模型（LLM）","text":"用海量文字訓練出來的 AI 模型，所以能閱讀和書寫語言。","also":["LLM","LLMs","大型語言模型","大語言模型"]},{"id":"genai","g":"ai","word":"生成式 AI","text":"能創造新東西（例如文字、圖片或程式碼）的 AI，而不只是分類或辨識。","also":["生成式 AI","生成式人工智慧","GenAI"]},{"id":"chatbot","g":"ai","word":"聊天機器人","text":"你可以用日常語言和它交談的程式，打字或說話都行。","also":["聊天機器人","對話機器人","chatbots"]},{"id":"prompt","g":"ai","word":"提示詞（Prompt）","text":"你交給 AI 的內容：你的問題或指示，加上你給它的任何資料。提示詞越清楚，通常得到的回答越好。","also":["提示詞","提示","指令","prompts"]},{"id":"prompteng","g":"ai","word":"提示詞工程","text":"寫出能得到可靠、有用結果的提示詞的技巧。","also":["提示詞工程","提示工程"]},{"id":"sysprompt","g":"ai","word":"系統提示詞","text":"AI 在對話開始前就收到的背景指示，設定它的角色和規則。它比你輸入的內容分量更重。","also":["系統提示詞","系統提示","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"上下文","text":"AI 工作時能看到的一切：指示、你的訊息、它讀過的檔案，以及之前的回覆。","noTip":1},{"id":"ctxwin","g":"ai","word":"上下文視窗","text":"AI 一次能記在心裡的量，以 token 計算。超過之後，較早的部分會被丟掉或改成摘要。","also":["上下文視窗","context windows"]},{"id":"session","g":"ai","word":"工作階段","text":"與 AI 的一次完整的工作對話，從頭到尾。新的工作階段從全新的記憶開始。","also":["工作階段","對話階段","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"記憶","text":"AI 在不同工作階段之間保留的筆記，讓它記得你的偏好和以前做過的決定。","noTip":1},{"id":"hallucination","g":"ai","word":"幻覺","text":"AI 說的話聽起來很有把握，其實是編出來的或是錯的。重要的事實要查證。","also":["幻覺","AI 幻覺","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"訓練","text":"在有人使用之前，讓模型看海量的範例來教會它。","also":["訓練","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"訓練資料","text":"模型學習所用的那些範例。它的知識截止到這些資料蒐集的日期。","also":["訓練資料","訓練集","training set"]},{"id":"cutoff","g":"ai","word":"知識截止日期","text":"AI 內建知識結束的日期。之後發生的事它不知道，除非它去查。","also":["知識截止日期","訓練截止日期","training cutoff"]},{"id":"finetune","g":"ai","word":"微調","text":"用你自己的範例替現成的模型額外訓練一輪，讓它更擅長某一項具體的工作。","also":["微調","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"推論","text":"AI 模型真正被用來回答問題，而不是在接受訓練。","also":["推論","模型推論","model inference"]},{"id":"tooluse","g":"ai","word":"工具呼叫","text":"AI 不只會說話，還能做事：透過應用程式提供給它的工具來執行指令、讀取檔案或搜尋網頁。","also":["工具呼叫","使用工具","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"子代理程式","text":"主 AI 把較小的工作交給它、並從它那裡拿回結果的幫手 AI。","also":["子代理程式","子代理","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"多代理程式","text":"好幾個 AI 一起處理同一項工作，各有各的分工，就像一個小團隊。","also":["多代理程式","多代理","多代理系統","multi-agent system"]},{"id":"autonomy","g":"ai","word":"自主性","text":"AI 在必須問人之前，可以自己做多少事。","also":["自主性","自主","autonomous"]},{"id":"hitl","g":"ai","word":"人在迴路","text":"讓人參與進來，在關鍵節點檢查或核准 AI 的所作所為。在 AI-gile 裡，這個人就是你。","also":["人在迴路","人工參與","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"護欄","text":"讓 AI 的行動保持安全的限制和檢查，例如任何東西上線前都要先得到核准。它們能降低出錯的風險，但不能完全杜絕。","also":["護欄","防護措施","guardrail"]},{"id":"rag","g":"ai","word":"檢索增強生成（RAG）","text":"讓 AI 在回答之前，先到你自己的文件裡查資料，這樣它的回答是以你的事實為依據的。","also":["RAG","檢索增強生成","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"嵌入（Embedding）","text":"把文字變成一串能代表其意思的數字，這樣電腦就能找出意思相近的內容。","also":["嵌入","向量嵌入","embeddings"]},{"id":"vectordb","g":"ai","word":"向量資料庫","text":"專門用來搜尋這些數字串（嵌入）的資料庫，用來找出含義相近的資料。","also":["向量資料庫","向量庫","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"模型上下文協定（MCP）","text":"把工具和資料來源接入 AI 應用程式的一種通用方式，這樣 AI 就能使用它們。","also":["MCP","模型上下文協定"]},{"id":"temperature","g":"ai","word":"溫度（Temperature）","text":"控制 AI 回答有多「大膽」的設定。低的話回答更穩定、更可預測；高的話更多變。但兩種都不能保證永遠正確。","also":["溫度","模型溫度","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"多模態","text":"能處理不只一種資訊，例如文字、圖片和聲音。","also":["多模態","multi-modal"]},{"id":"evals","g":"ai","word":"評估（Eval）","text":"用挑選好的範例，有計畫地測試 AI 表現如何，這樣可以比較不同的模型或提示詞。","also":["評估","評測","eval","evals"]},{"id":"bias","g":"ai","word":"偏見","text":"AI（或人）不公平地偏向某一邊，往往是因為它學習的資料有偏。","also":["偏見","偏差","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"負責任的 AI","text":"公平、安全、誠實地使用 AI，並且結果仍由人來負責。","also":["負責任的 AI","AI 倫理","ethical AI"]},{"id":"injection","g":"ai","word":"提示詞注入","text":"一種花招：網頁或檔案裡藏著的指示，企圖讓 AI 去做使用者沒有要求的事。","also":["提示詞注入","提示注入","prompt injections"]},{"id":"ratelimit","g":"ai","word":"速率限制","text":"在一定時間內，你能向服務傳送多少請求的上限。超過了就得等一等。","also":["速率限制","限流","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"用量上限","text":"你的方案在一段時間內允許多少 AI 工作量，超過之後會暫停或要多付錢。","also":["用量上限","使用限額","usage limits"]},{"id":"vibe","g":"ai","word":"氛圍程式設計（Vibe coding）","text":"主要靠向 AI 描述你想要什麼、讓它來寫程式碼，從而做出軟體。","also":["氛圍程式設計","氛圍編程","vibe-coding"]},{"id":"budget","g":"money","word":"預算","text":"為某件事預留的錢。","also":["預算","budgets"],"noTip":1},{"id":"costest","g":"money","word":"成本估算","text":"在開始之前，對某件事要花多少錢的最佳猜測。","also":["成本估算","費用估算","cost estimates"]},{"id":"roi","g":"money","word":"投資報酬率（ROI）","text":"你得到的回報與你投入的相比如何。如果是正數，就表示值得。","also":["ROI","投資報酬","投資報酬率"]},{"id":"tco","g":"money","word":"總持有成本（TCO）","text":"某樣東西在整個生命週期裡真正的全部花費，而不只是買它的價錢：營運、支援、升級，最後還有淘汰它。","also":["TCO","總持有成本"]},{"id":"capex","g":"money","word":"資本支出與營運支出（CapEx 和 OpEx）","text":"CapEx 是一次性預先花在能長期保留的東西上的錢；OpEx 是持續的支出，例如每月的帳單。","also":["CapEx","OpEx","資本支出","營運支出","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"訂閱","text":"定期付費（通常按月或按年），以便繼續使用某樣東西。","also":["訂閱","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"軟體即服務（SaaS）","text":"在線上使用、按訂閱付費的軟體，由開發商替你營運。","also":["SaaS","軟體即服務"]},{"id":"payg","g":"money","word":"用多少付多少","text":"只為你用到的部分付錢，例如雲端運算或 AI 的 token。","also":["用多少付多少","按量計費","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"超額使用","text":"用量超出方案包含的部分，可能要額外收費。","also":["超額使用","超出用量","overages","overage charges"]},{"id":"billingalert","g":"money","word":"帳單提醒","text":"花費或用量達到你設定的水準時發出的訊息。它會提醒你，但不一定會阻止之後繼續扣款。","also":["帳單提醒","費用提醒","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"免費方案","text":"付費服務裡帶有限制的免費層級。剛開始用很方便。","also":["免費方案","免費額度","free plan"]},{"id":"pricing","g":"money","word":"定價方案","text":"一項服務出售的各種方案，每種有自己的價格和限制。","also":["定價方案","價格方案","pricing plans","price plan"]},{"id":"licence","g":"money","word":"授權","text":"規定你可以怎樣使用、複製、修改或分享別人做的東西（例如軟體、字型或圖片）的規則。","also":["授權","授權條款","licences","license","licenses","licence"],"noTip":1},{"id":"opensource","g":"money","word":"開放原始碼","text":"程式碼人人都能閱讀、使用、而且往往可以免費修改的軟體，要遵守其授權條款的規定。","also":["開放原始碼","開源","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"開放原始碼授權","text":"開放原始碼附帶的規則。有的幾乎什麼都允許（例如 MIT），有的要求你也分享你的修改（例如 GPL）。","also":["開放原始碼授權","開源授權","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"專有軟體","text":"歸某家公司所有，不能隨便複製或修改。與開放原始碼相反。","also":["專有軟體","閉源軟體","proprietary software"]},{"id":"copyright","g":"money","word":"著作權","text":"創作者控制自己作品（包括程式碼和文字）的複製的法定權利。","also":["著作權","版權","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"智慧財產權（IP）","text":"法律視為有所有者的想法和創作，例如程式碼、設計、名稱和標誌。","also":["智慧財產權","intellectual property"]},{"id":"tos","g":"money","word":"服務條款","text":"你使用某項服務時所同意的規則。","also":["服務條款","使用條款","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"合約","text":"雙方之間的書面協議，受到法律保護。","also":["合約","契約","contracts"],"noTip":1},{"id":"sow","g":"money","word":"工作說明書（SOW）","text":"一份文件，寫明具體要做哪些工作、什麼時候完成、收多少錢。","also":["SOW","工作說明書"]},{"id":"fixedprice","g":"money","word":"固定價格","text":"整項工作約定好一個價格，不管花多長時間。","also":["固定價格","固定報價","fixed-price"]},{"id":"tm","g":"money","word":"按工時與材料計費","text":"依實際做的工時和實際用到的東西付費，而不是固定價格。","also":["按工時計費","T&M"]},{"id":"invoice","g":"money","word":"請款單（Invoice）","text":"為已完成的工作或已提供的商品要求付款的帳單。","also":["請款單","發票","帳單","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"供應商綁定","text":"離開某個供應商太難或太貴，結果你只好一直被它綁住。","also":["供應商綁定","廠商綁定","lock-in"]},{"id":"procurement","g":"money","word":"採購","text":"挑選並向供應商購買東西的過程。","also":["採購"]},{"id":"servicecredit","g":"money","word":"服務抵扣金","text":"供應商沒達到 SLA 時，你得到的退款或折扣。","also":["服務抵扣金","服務補償","service credits"]}]}};
